window.__D("b:VY02",{"id":"VY02","hero":{"h1":"כי ידעתיו: האב שמצווה את בניו","lead":"<strong>ביאור על שרשרת המאמרים <span class=\"qt\">״כי ידעתיו למען אשר יצוה את בניו״<\/span> (בראשית יח, יט), מאדמו״ר מהר״ש ועד הרבי — ולצידה מה שהמקורות עצמם אומרים על כ׳ מרחשון<\/strong>","status":"<em>חברותא · פרשת וירא · כ׳ מרחשון · שלב 3 (ביאורים) · טיוטה אחרי בקרה פנימית עיוורת; בקרה משלימה חלקית, 26.10.2026<\/em>"},"html":"\n\n\n<hr/>\n<section class=\"part\" data-part=\"intro\" id=\"intro\"><div class=\"part-head\"><h2 id=\"h-intro\">פתח דבר: פסוק אחד, שבעה דורות, ושבת אחת שבה הפרשה והיום נפגשים<\/h2><\/div>\n<p id=\"x4c6248\"><em>השנה חל כ׳ מרחשון, יום הולדת אדמו״ר הרש״ב, בשבת פרשת וירא. הפסוק <span class=\"qt cite\" data-ex=\"MZSH-3\" data-n=\"VY02:MZ-SH\">״כי ידעתיו למען אשר יצוה את בניו״<\/span> הוא פסוק של אב ובניו; כאן נקרא את המאמרים עליו, ונבדוק מה הם עצמם אומרים על היום.<\/em><\/p>\n<p id=\"x461015\">כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך ה׳ לעשות צדקה ומשפט למען הביא ה׳ על אברהם את אשר דבר עליו (בראשית יח, יט). הקב״ה אומר זאת לפני שהוא מגלה לאברהם את דבר סדום. יש בפסוק שלוש שאלות שהמאמרים חוזרים אליהן שוב ושוב: מה פירוש <span class=\"qt\">״ידעתיו״<\/span> — ידיעה או חיבה? מה <span class=\"qt\">״לעשות צדקה ומשפט״<\/span> מוסיפים על <span class=\"qt\">״ושמרו דרך ה׳״<\/span>? ומה פירוש <span class=\"qt\">״על אברהם״<\/span> — <span class=\"qt\">״עליו״<\/span>, ולא <span class=\"qt\">״לו״<\/span>?<\/p>\n<p id=\"x133916\">אלה המאמרים שקראנו:<\/p>\n<div aria-label=\"טבלה (גלילה לצדדים)\" class=\"scroll\" role=\"region\" tabindex=\"0\"><table>\n<thead>\n<tr id=\"x7d41d6\">\n<th>הרבי<\/th>\n<th>המאמר<\/th>\n<th>נאמר<\/th>\n<th>מעמד (לפי המקור)<\/th>\n<th>איפה קראנו<\/th>\n<\/tr>\n<\/thead>\n<tbody>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:MH-627\" id=\"x8add28\">\n<td>אדמו״ר מהר״ש<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt\">״(ש״פ וירא) ך״ז״<\/span><\/td>\n<td><span class=\"qt\">״ד״ה זה להצ״צ״<\/span> בהנחת מהר״ש, <span class=\"qt\">״בתוס׳ הגהות״<\/span> (המו״ל)<\/td>\n<td>תורת שמואל תרכ״ז, ע׳ טז–כב (צילום <span class=\"ltr\" dir=\"ltr\">COL<\/span>; גוף המאמר גם בספריית חב״ד)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:MH-634\" id=\"xfab643\">\n<td>אדמו״ר מהר״ש<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt\">״ש״פ וירא״<\/span>, תרל״ד<\/td>\n<td><span class=\"qt cite\" data-ex=\"MH634-2\" data-n=\"VY02:MH-634\">״ד״ה זה דשנת תרכ״ז... בכמה שינויים קלים״<\/span> (המו״ל)<\/td>\n<td>תורת שמואל תרל״ד, ע׳ מז–נג (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:RS-666\" id=\"xe04ab3\">\n<td>אדמו״ר הרש״ב<\/td>\n<td>כי ידעתיו (המאמר הראשון בפרשת וירא שבהמשך תרס״ו)<\/td>\n<td><span class=\"qt\">״ש״פ וירא, רס״ו״<\/span>; בכותרת העמודים: <span class=\"qt\">״כ״ף מרחשון״<\/span><\/td>\n<td>מכתב יד קדשו<\/td>\n<td>סה״מ תרס״ו (מהדורה חדשה), ע׳ צא–קג (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr id=\"xaac475\">\n<td>אדמו״ר הרש״ב<\/td>\n<td>והוי׳ אמר המכסה (המאמר השני)<\/td>\n<td><span class=\"qt\">״ש״פ וירא, רס״ז״<\/span>; בכותרת העמודים: <span class=\"qt\">״ט״ו מרחשון״<\/span><\/td>\n<td>—<\/td>\n<td>שם, ע׳ תקכה–תקלז (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:RS-680\" id=\"x9b1f52\">\n<td>אדמו״ר הרש״ב<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt\">״ש״פ וירא, פר״ת״<\/span><\/td>\n<td><span class=\"qt\">״בגוכי״ק״<\/span><\/td>\n<td>סה״מ תר״פ, ע׳ קלב–קמ (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:RY-684\" id=\"x514543\">\n<td>אדמו״ר הריי״צ<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt\">״ש״פ וירא, רפ״ד״<\/span><\/td>\n<td>ההמשך <span class=\"qt\">״נכתב... בקונטרס״<\/span>, ונוספו עליו <span class=\"qt cite\" data-ex=\"RY684-11\" data-n=\"VY02:RY-684/מפתח\">״הגהות והתחלת וסוף כל מאמר״<\/span><\/td>\n<td>סה״מ תרפ״ד, ע׳ פ–צג (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"high\" data-n=\"VY02:RY-707\" id=\"xd2f753\">\n<td>אדמו״ר הריי״צ<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt\">״ש״פ וירא, תש״ז״<\/span><\/td>\n<td>—<\/td>\n<td>סה״מ תש״ז, ע׳ 188–195 (<span class=\"ltr\" dir=\"ltr\">COL<\/span>)<\/td>\n<\/tr>\n<tr class=\"rowref\" data-conf=\"likely\" data-n=\"VY02:RB-736\" id=\"x16ce80\">\n<td>הרבי<\/td>\n<td>כי ידעתיו<\/td>\n<td><span class=\"qt cite\" data-ex=\"RB736-0\" data-n=\"VY02:RB-736/כותרת\">״ש״פ וירא, כ׳ מרחשון ה׳תשל״ו״<\/span><\/td>\n<td><span class=\"qt\">״כעין שיחה״<\/span>, <span class=\"qt\">״חסר הסיום״<\/span><\/td>\n<td>סה״מ בראשית ח״א ע׳ ריד ואילך (<span class=\"ltr\" dir=\"ltr\">maamarim.com<\/span>)<\/td>\n<\/tr>\n<tr id=\"xeb32c9\">\n<td>הרבי<\/td>\n<td>וה׳ אמר המכסה<\/td>\n<td><span class=\"qt cite\" data-ex=\"RB737-1\" data-n=\"VY02:RB-737\">״ש״פ וירא, כ״ף מרחשון ה׳תשל״ז״<\/span><\/td>\n<td>מוגה (לפי פתח הדבר של <span class=\"qt\">״ספר המאמרים מלוקט״<\/span>; ראו פרק ח)<\/td>\n<td>סה״מ מלוקט ח״א, ע׳ רנה–רסא (ספריית חב״ד)<\/td>\n<\/tr>\n<\/tbody>\n<\/table><\/div>\n<p id=\"x2f2790\">לפני מהר״ש עומדים כמה טקסטים, וצירופם לשרשרת הוא שלנו <strong><span class=\"smark\">[סינתזה]<\/span><\/strong>, על סמך הפניות המו״לים: ד״ה <span class=\"qt\">״אז ישיר״<\/span> בתורה אור בשלח של אדמו״ר הזקן, שאליו מפנים המו״ל בתרכ״ז והרבי בתשל״ז; ד״ה <span class=\"qt\">״אשירה״<\/span> של אדמו״ר האמצעי, שלפי המו״ל <span class=\"qt cite\" data-ex=\"MZSH-1\" data-n=\"VY02:MZ-SH\">״מיוסד על ד״ה זה בתורה אור״<\/span>, וביאורו בתורת חיים; הנחה של אדמו״ר האמצעי מאחרון של פסח תקע״ז, שאליה מפנה המו״ל בתורת חיים; ומאמר קצר של אדמו״ר הזקן, <span class=\"qt\">״המכסה אני מאברהם״<\/span> (הוספות), שמפרש גם את פסוקנו, ושאליו לא מצאנו הפניה. המאמרים של הצמח צדק באור התורה וירא, וד״ה <span class=\"qt\">״כי ידעתיו״<\/span> של הריי״צ מתרפ״ו, ידועים לנו רק מהפניות; את תוכנם לא קראנו, ולא נתאר אותו.<\/p>\n<p id=\"x3b7845\">שלושה טקסטים נוספים אינם על הפסוק כפשוטו, אבל מקושרים במפורש לכ׳ מרחשון: המאמר שאמר מהר״ש בבר המצוה של בנו, אדמו״ר הרש״ב, <span class=\"qt\">״כי נר מצוה״<\/span> של הריי״צ מכ׳ מרחשון תרצ״ב, ושיחת הרבי מש״פ וירא, כ״ף מרחשון תשמ״ז. נביא אותם בפרק האחרון.<\/p>\n<p id=\"xe1ef16\"><strong>איך לקרוא את הביאור.<\/strong> דברי המאמרים מובאים בלשונם, במירכאות, עם ציון העמוד. ההסבר כתוב בלשון פשוטה. קשר בין מאמרים נכתב רק כשאחד המקורות עושה אותו: המחבר, או המו״ל בהערה. כשהקשר הוא שלנו, הוא מסומן <strong><span class=\"smark\">[סינתזה]<\/span><\/strong>. הקטעים המצוטטים שמורים בקובץ הקטעים, וכל ציטוט מכרכי <span class=\"ltr\" dir=\"ltr\">COL<\/span> הועתק מצילום הדף.<\/p>\n<p id=\"x70a8c3\"><strong>ראשי תיבות שבציטוטים<\/strong> (לפי סדר הא״ב): אאע״ה — אברהם אבינו עליו השלום · או״ח — אור חוזר · אוא״ס, א״ס — אור אין סוף, אין סוף · אתעדל״ע / אתעדל״ת — התעוררות מלמעלה / מלמטה · ז״א — זעיר אנפין · מ״ת — מתן תורה · מ״ע, ל״ת — מצוות עשה, לא תעשה · מעהמ״צ — מעשה המצוות · נש״י — נשמות ישראל · פו״מ — פועל ממש · קבעומ״ש — קבלת עול מלכות שמים · רמ״ח, שס״ה — מאתיים ארבעים ושמונה, שלוש מאות שישים וחמש · תומ״צ — תורה ומצוות · ת״א — תרגום אונקלוס · תושב״כ — תורה שבכתב.<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-א\" id=\"ch-א\"><div class=\"part-head\"><h2 id=\"h-ch-א\">א. השורש: צדקה ומשפט הם <span class=\"qt\">״דרך כלל״<\/span> כל המצוות, והמשפט הוא גבול לתענוגות<\/h2><\/div>\n<p id=\"xbd5328\"><em>באדמו״ר הזקן ובאדמו״ר האמצעי הפסוק מופיע בתוך מאמרים על שירת הים. עוד שם צדקה ומשפט הן כלל התורה, ו״משפט״ פירושו שהאדם שופט את עצמו על המותרות.<\/em><\/p>\n<p id=\"x157c2e\"><strong>תורה אור.<\/strong> בד״ה <span class=\"qt\">״אז ישיר״<\/span> אדמו״ר הזקן מסביר שגם התורה וגם המצוות מעלות את הנפש למקום שהיא עצמה אינה מגיעה אליו, ומוסיף: <span class=\"qt cite\" data-ex=\"AZ-1\" data-n=\"VY02:AZ-TO\">״וכמו שהוא לענין תורה כך הוא לענין שאר מצות דכתיב ושמרו דרך ה׳ לעשות צדקה ומשפט למען הביא ה׳ על אברהם את אשר דבר עליו שע״י המצות שנקראו דרך כלל בשם צדקה ומשפט כמו שיתבאר נמשך על בחי׳ אברהם שהיא מדת האהבה ברצוא הלוך ונסוע״<\/span> (סג, א). כלומר: <span class=\"qt\">״צדקה ומשפט״<\/span> הוא שם כולל לכל המצוות, ואברהם הוא מידת האהבה. (<span class=\"edn\">הערת המהדורה<\/span>: <span class=\"qt\">״רצוא״<\/span> בלשון החסידות הוא תשוקת הנפש לעלות ולהתכלל.)<\/p>\n<p id=\"x87df06\">שם גם הגדרה של <span class=\"qt\">״דרך״<\/span>: <span class=\"qt cite\" data-ex=\"AZ-2\" data-n=\"VY02:AZ-TO\">״פירוש דרך ומבוא להיות הוי׳״<\/span> — הדרך שבה שם הוי׳ נכנס לעולם — <span class=\"qt cite\" data-ex=\"AZ-3\" data-n=\"VY02:AZ-TO\">״והיא על ידי אתערותא דלתתא בצדקה ומשפט שהן דרך כלל כל מצות התורה״<\/span> (סג, ב). והמשפט מתפרש כגבול שהאדם שם לעצמו: <span class=\"qt cite\" data-ex=\"AZ-4\" data-n=\"VY02:AZ-TO\">״ובחי׳ משפט זה אשר לאלהים הוא על ידי אתערותא דלתתא בחי׳ משפט שעושה האדם בנפשו על מותרות חיי גופו נגד הצדקה״<\/span>. ומשל: <span class=\"qt cite\" data-ex=\"AZ-4\" data-n=\"VY02:AZ-TO\">״חייך קודמין לחיי חבירך ודוקא חייך ממש כמשל הקיתון של מים... מה שאין כן המותרות שלך אינן קודמין לחיי חבירך שאינו בדין שיפנק האדם את נפשו בתפנוקי עלמא וחבירו ימות ברעב ח״ו״<\/span> (סג, ב). ובעמוד שאחריו: <span class=\"qt cite\" data-ex=\"AZ-5\" data-n=\"VY02:AZ-TO\">״והנה גם שאר מצות התורה נקראות בשם צדקה על דרך זה כי רמ״ח מצות עשה הם רמ״ח אברין דמלכא״<\/span> (סג, ג).<\/p>\n<p id=\"xefbc09\"><strong><span class=\"qt\">״המכסה״<\/span> (הוספות).<\/strong> במאמר קצר על <span class=\"qt\">״המכסה אני מאברהם״<\/span> אדמו״ר הזקן מפרש גם את פסוקנו, ומשווה את <span class=\"qt\">״דרך הוי׳״<\/span> לדרך ממש: <span class=\"qt cite\" data-ex=\"AZH-1\" data-n=\"VY02:AZ-HOS\">״פי׳ דרך הוי׳ כמשל דרך הגשמי שבו עוברים ממקום למקום כן ארחות הוי׳ חסד כו׳ המתפשט מלמעלה למטה מאצי׳ לבי״ע, ויש חסד העולה מלמטה למעלה״<\/span> (הוספות/וירא, ע׳ 6). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> שני הכיוונים ומשל הדרך יחזרו בתרס״ז ובתשל״ז; אף אחד מהם אינו מפנה לכאן.<\/p>\n<p id=\"xe39349\"><strong>אדמו״ר האמצעי, <span class=\"qt\">״אשירה״<\/span>.<\/strong> המו״ל כותב: <span class=\"qt cite\" data-ex=\"MZSH-1\" data-n=\"VY02:MZ-SH\">״המאמר מיוסד על ד״ה זה בתורה אור בשלח סב, ד״<\/span> (קח). ואכן, אותו עניין חוזר בהרחבה: <span class=\"qt cite\" data-ex=\"MZSH-2\" data-n=\"VY02:MZ-SH\">״ובכל זה יובן מה שהזכיר מדת משפט בצדקה... הכל מטעם הנ״ל בכדי שלא יתעורר אתעדל״ע לבחי׳ המותרות אלא רק להחיות רוח שפלים במקום מותרות כו׳״<\/span> (קטז). ומשם אל הפסוק: <span class=\"qt cite\" data-ex=\"MZSH-3\" data-n=\"VY02:MZ-SH\">״וזהו המשך דברי הפסוק כי ידעתיו... פי׳ למען הביא על אברהם כו׳ כי בחי׳ אברהם הי׳ בבחי׳ רצוא ושוב״<\/span> (קטז). ומה פירוש <span class=\"qt\">״עליו״<\/span>? <span class=\"qt cite\" data-ex=\"MZSH-4\" data-n=\"VY02:MZ-SH\">״פי׳ עליו למעלה הימנו דוקא, והוא בחי׳ אדון הנפלאות הנ״ל שע״י דביקות הנפש לא תגיע לזה רק דוקא ע״י עסק התורה ומצות שנק׳ צדק[ה] ומשפט״<\/span> (קיז). כלומר, מה שהבטיח הקב״ה <span class=\"qt\">״על אברהם״<\/span> הוא דרגה שמעליו — והוא מגיע אליה דווקא דרך המצוות.<\/p>\n<p id=\"x677f9e\"><strong>תורת חיים: שאלה חדה.<\/strong> בביאור על אותו ד״ה (תורת חיים) אדמו״ר האמצעי מנסח שאלה שתחזור בהמשך השרשרת (<strong><span class=\"smark\">[סינתזה]<\/span><\/strong>: בתרס״ז ובתשל״ז; הם אינם מפנים לכאן): אם <span class=\"qt\">״דרך הוי׳״<\/span> הוא כלל המצוות, <span class=\"qt cite\" data-ex=\"MZTC-1\" data-n=\"VY02:MZ-TC\">״וא״כ יש להבין מ״ש עוד לעשות צדקה ומשפט... ומה זה שכפל הדברים לומר ב׳ דברים שמירה בדרך הוי׳ ועשי׳ בצדקה כו׳״<\/span> (קסט, ג). ותשובתו: השמירה היא בכוונה ובלב — <span class=\"qt cite\" data-ex=\"MZTC-2\" data-n=\"VY02:MZ-TC\">״וז״ש אשר יצוה את בניו ושמרו דרך הוי׳ שיצוה להם שיהי׳ בהם הכח ועוז לשמור דרך הוי׳, וכל שמירה הוא במח׳ וכוונה ורעותא דלבא״<\/span> (קסט, ד) — והעשייה היא המעשה בפועל. וב״למען הביא״ — <span class=\"qt cite\" data-ex=\"MZTC-3\" data-n=\"VY02:MZ-TC\">״להעלותו למעלה משרשו הראשון״<\/span> (קעה, ג).<\/p>\n<aside class=\"synth\"><p id=\"x3678e0\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> כבר כאן <span class=\"qt cite\" data-ex=\"MZSH-3\" data-n=\"VY02:MZ-SH\">״אשר יצוה את בניו״<\/span> מתפרש כהעברה של כוח: האב מצווה כדי <span class=\"qt cite\" data-ex=\"MZTC-2\" data-n=\"VY02:MZ-TC\">״שיהי׳ בהם הכח ועוז״<\/span>. הרבי יאמר דבר קרוב בתשל״ז (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%97\" title=\"ח. הרבי, תשל״ז: שני המאמרים של הרש״ב, ו״אשר יצוה את בניו״ כנתינת כוח לכל אחד מישראל\">פרק ח<\/a>), אבל הוא אינו מפנה לתורת חיים.<\/p><\/aside>\n<p id=\"x4c3f8d\"><strong>הנחות תקע״ז: שני הפכים.<\/strong> גם בתורת חיים כתוב: <span class=\"qt cite\" data-ex=\"MZTC-5\" data-n=\"VY02:MZ-TC\">״דלכאו׳ הצדקה והמשפט הן ב׳ הפכים״<\/span> (קע, א). בהנחה שכותרתה <span class=\"qt cite\" data-ex=\"M577-1\" data-n=\"VY02:MZ-577\">״אחרון של פסח, תקע״ז״<\/span> זו שאלת הפתיחה: <span class=\"qt cite\" data-ex=\"M577-2\" data-n=\"VY02:MZ-577\">״וצ״ל ענין הסמיכות צדקה למשפט כי צדקה ומשפט המה שני הפכים בתכלית, כי הצדקה היא לפנים משורת הדין ומשפט הוא להיות מכלכל דבריו במשפט דייקא כו׳״<\/span> (נח). התשובה עוברת דרך שני מיני רחמים, ומשל (שנמצא גם בתורת חיים, קעא, ג: <span class=\"qt cite\" data-ex=\"MZTC-6\" data-n=\"VY02:MZ-TC\">״כמו המלך המרומם ביותר שירחם על העני ושפל יותר מעל השר הגדול״<\/span>): <span class=\"qt cite\" data-ex=\"M577-3\" data-n=\"VY02:MZ-577\">״כמו למשל מלך המתנשא בתכלית הרוממות אזי יפול אצלו רחמנות על השפל ביותר... משא״כ שר אשר אינו בהתנשאות כמו המלך לא ירחם כ״כ על השפל ביותר כו׳״<\/span> (נט). והמשפט שוב נוגע במותרות — במי שנותן צדקה <span class=\"qt cite\" data-ex=\"M577-4\" data-n=\"VY02:MZ-577\">״רק מהסך הנשאר אחר בזבוז על המותרות״<\/span> (ס). את ההנחה הזאת קישר לשרשרת המו״ל בתורת חיים, שמפנה אליה בהערה: <span class=\"qt cite\" data-ex=\"MZTC-4\" data-n=\"VY02:MZ-TC\">״הנחות תקע״ז כאן (ע׳ נט)״<\/span>.<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ב\" id=\"ch-ב\"><div class=\"part-head\"><h2 id=\"h-ch-ב\">ב. מהר״ש: ממאמר של הצמח צדק — המבנה שחוזר אחריו<\/h2><\/div>\n<p id=\"xf1e47c\"><em>לפי המו״ל, מאמר מהר״ש הוא <span class=\"qt\">״ד״ה זה להצ״צ״<\/span> בהנחת מהר״ש. בו מובאים ומתפתחים הקושיות, דרשת ר׳ שמלאי, עניים ועשירים, ומשל המשקה והעודר — ובסוף, בלשון <span class=\"qt\">״ואפ״ל״<\/span>, הבחירה. שתי נקודות כבר מיוחסות באותה מהדורה לאור התורה פט, א: <span class=\"qt\">״ידעתיו״<\/span> לשון חיבה, והבחירה בשם הפנים יפות; בגוף מאמר מהר״ש שתיהן מובאות; החיבה מתפתחת במשל, ואילו הבחירה נחתמת בקיצור ובלשון <span class=\"qt\">״ואפ״ל״<\/span>.<\/em><\/p>\n<p id=\"x8d7678\"><strong>מאיפה המאמר.<\/strong> בראש המאמר כותב המו״ל: <span class=\"qt cite\" data-ex=\"MH627-3\" data-n=\"VY02:MH-627\">״הוא ד״ה זה להצ״צ בגוכי״ק כ״ק אדמו״ר מהר״ש בכת״י 1077... [הכולל הנחות אדמו״ר מהר״ש ממאמרי הצ״צ]. וכאן הוא בתוס׳ הגהות. תוכן המאמר נמצא בקיצור (כפי שנרשם ע״י הצ״צ) בד״ה זה באוה״ת וירא צו, א״<\/span> (טז). והוא ממשיך ומונה את גלגולי המאמר: <span class=\"qt cite\" data-ex=\"MH627-4\" data-n=\"VY02:MH-627\">״המאמר נמצא בשינויים קלים בד״ה זה בסה״מ תרל״ד... ובתוס׳ ביאור והוספות בד״ה זה בסה״מ פר״ת... ובד״ה זה בסה״מ תרפ״ו... ובד״ה זה היום עשה הוי׳ בסה״מ תרפ״ח... ובסה״מ תש״ח״<\/span>. אור התורה צו, א מתואר אפוא כקיצור התוכן; אור התורה פט, א–ב משמש מקור להתחלת המאמר ולסיומו, ובפרט לחיבה ולבחירה. את שני המקומות באור התורה לא פתחנו, ולכן היחס המדויק בין נוסחיהם ובין גוף מאמר מהר״ש לא הוכרע.<\/p>\n<p id=\"xc1c4a0\"><strong>המאמר כותרתו <span class=\"qt cite\" data-ex=\"MH627-1\" data-n=\"VY02:MH-627\">״בס״ד. (ש״פ וירא) ך״ז.״<\/span><\/strong>, והוא נפתח בשתי קושיות. הראשונה על הפירוש: <span class=\"qt cite\" data-ex=\"MH627-2\" data-n=\"VY02:MH-627\">״שאונקלוס תרגם לשון כי ידעתיו ארי גלי קדמי, ורש״י פי׳ כי ידעתיו לשון חיבה, דלפי פי׳ הת״א אין למען נופל על הלשון״<\/span> (טז). (<span class=\"qt\">״ארי גלי קדמי״<\/span> — כי גלוי לפניי.) כלומר: אם <span class=\"qt\">״ידעתיו״<\/span> פירושו ידיעה מראש, מה עושה כאן <span class=\"qt\">״למען״<\/span> — <span class=\"qt\">״בשביל״<\/span>? השנייה על אברהם: <span class=\"qt cite\" data-ex=\"MH627-2\" data-n=\"VY02:MH-627\">״קיים אברהם כל התורה כולה עד שלא ניתנה״<\/span> — אבל איך, <span class=\"qt cite\" data-ex=\"MH627-2\" data-n=\"VY02:MH-627\">״כמו מצות תפילין שהם ד׳ פרשיות קדש והי׳ כי יביאך שמבואר סיפור יצ״מ ועדיין לא הי׳ שעבוד מצרים״<\/span> (טז)?<\/p>\n<p id=\"x983d30\"><strong>ר׳ שמלאי.<\/strong> התשובה מתחילה במכות: דוד העמיד את המצוות על אחת עשרה, ישעיה על שתיים, חבקוק על אחת. אין זה ביטול של שאר המצוות: <span class=\"qt cite\" data-ex=\"MH627-6\" data-n=\"VY02:MH-627\">״שדוד אמר שכ״א יקיים הי״א מדות אלו וממילא יבא על ידם לקיום כל התרי״ג מצות״<\/span> (טז). <span class=\"qt cite\" data-ex=\"MH627-7\" data-n=\"VY02:MH-627\">״ובא ישעי׳ והעמידן על שנים שהם צדקה ומשפט, לפי שב׳ מצות אלו הם מקור לכל התרי״ג מצות, וכמשי״ת, וז״ש באברהם ושמרו דרך ה׳ לעשות צדקה ומשפט״<\/span> (יז). מכאן — צדקה היא <span class=\"qt\">״שורש לרמ״ח מ״ע״<\/span> (יט), וגם <span class=\"qt cite\" data-ex=\"MH627-12\" data-n=\"VY02:MH-627\">״המשפט הוא שרש לשס״ה ל״ת״<\/span> (כ). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> זה קרוב מאוד ללשון תורה אור — <span class=\"qt cite\" data-ex=\"AZ-3\" data-n=\"VY02:AZ-TO\">״דרך כלל כל מצות התורה״<\/span>; מהר״ש אינו מצטט את תורה אור, אבל המו״ל מפנה לשם (<span class=\"qt cite\" data-ex=\"MH627-9\" data-n=\"VY02:MH-627\">״בהבא לקמן (בענין לעשות צדקה ומשפט) ראה תו״א בשלח סג, סע״א ואילך״<\/span>, יח).<\/p>\n<p id=\"x56c5a7\"><strong>למה בעולם יש עניים.<\/strong> <span class=\"qt cite\" data-ex=\"MH627-8\" data-n=\"VY02:MH-627\">״ולכאו׳ צ״ל למה הי׳ לו ית׳ לבראות עניים ועשירים... דהי׳ לו לעשות שכאו״א יהי׳ לו כדי פרנסתו ולא יצטרכו עמך ישראל זה לזה״<\/span> (יח). התשובה בשמש ובלבנה: השמש עשירה, הלבנה <span class=\"qt cite\" data-ex=\"MH627-24\" data-n=\"VY02:MH-627\">״עני דלית לי׳ מגרמי׳ כלום״<\/span>, וההשפעה ביניהן היא צדקה. ובאדם: <span class=\"qt cite\" data-ex=\"MH627-10\" data-n=\"VY02:MH-627\">״ע״י מה שנותן העשיר צדקה למטה עי״ז נמשך בחי׳ הצדקה למעלה כו׳, והיינו ע״י בחי׳ הביטול שמה שמשתכר ביגיע כפו נותן לחבירו״<\/span> (יט).<\/p>\n<p id=\"x5d3563\"><strong>משפט: כל אחד במקומו.<\/strong> משפט פירושו סדר. <span class=\"qt cite\" data-ex=\"MH627-11\" data-n=\"VY02:MH-627\">״וארז״ל בירושלמי וכי יש משפט לעצים אלא קרש שזכה בדרום ינתן בדרום, והיינו שכ״א על מקומו יבא בשלום״<\/span> (יט). ומכאן להפרדת הטוב מן הרע: <span class=\"qt cite\" data-ex=\"MH627-12\" data-n=\"VY02:MH-627\">״וענין המשפט הוא לבער הרע ולברור אותו מן הטוב כו׳״<\/span> (כ).<\/p>\n<p id=\"x65cb68\"><strong>מה נתחדש במתן תורה.<\/strong> אם אברהם קיים הכול, מה הוסיף משה? <span class=\"qt cite\" data-ex=\"MH627-13\" data-n=\"VY02:MH-627\">״אברהם שקיים התורה עי״ז המשיך גילוי אלקות למעלה... אך להיות נמשך המשכת אלקותו ית׳ ע״י המצות גשמי׳ זהו ענין התחדשות מ״ת״<\/span> (כ). וזה פירוש <span class=\"qt\">״על אברהם״<\/span>: <span class=\"qt cite\" data-ex=\"MH627-14\" data-n=\"VY02:MH-627\">״כי על בחי׳ החסד דאברהם הביא עליו בחי׳ חסד דמשה דאקרי רב חסד״<\/span> (כא). ובכל זאת <span class=\"qt cite\" data-ex=\"MH627-14\" data-n=\"VY02:MH-627\">״האבות עשו הכנה למ״ת״<\/span>: <span class=\"qt cite\" data-ex=\"MH627-15\" data-n=\"VY02:MH-627\">״וזהו ושמרו דרך הוי׳ שעשו בחי׳ שם הוי׳ יו״ד צמצום ה׳ התפשטות וא״ו המשכה כו׳, וע״י הכנה זו שעשו המשיך משה אח״כ למטה״<\/span> (כא) — כמו דוד, שהכין את כל חומרי המקדש, ושלמה בנה.<\/p>\n<p id=\"x1112dd\"><strong>ידעתיו — חיבה.<\/strong> <span class=\"qt cite\" data-ex=\"MH627-16\" data-n=\"VY02:MH-627\">״כי ל׳ ידעתיו ל׳ ידיעה אינו שייך לומר שעכשיו ידע ומקודם לא ידע, רק שפי׳ ידעתיו הוא לשון חיבה כמו רק אתכם ידעתי מכל העמים״<\/span> (כא). המו״ל מפנה כאן לאור התורה וירא פט, א, ומעתיק ממנו את עצם פירוש רש״י ואת הראיה מן הפסוק רק אתכם ידעתי; אצל מהר״ש הדברים מובאים ומתפתחים במשל. <span class=\"qt cite\" data-ex=\"MH627-17\" data-n=\"VY02:MH-627\">״משל לאחד כשהוא משקה משקה לכל השדה, כשהוא עודר אינו עודר אלא הטובים״<\/span> (כא–כב). השקיה היא עבודה כללית, ועידור — עבודה פרטית, <span class=\"qt cite\" data-ex=\"MH627-17\" data-n=\"VY02:MH-627\">״ויתרון על המלאכה כלליות״<\/span>. <span class=\"qt cite\" data-ex=\"MH627-18\" data-n=\"VY02:MH-627\">״וכך יובן זה למעלה... כשהוא עודר דהיינו בחי׳ השפעה פנימיות בחי׳ תומ״צ אינו עודר אלא הטובים... וזהו כי ידעתיו שהוא ל׳ חיבה למען אשר יצוה״<\/span> (כב).<\/p>\n<p id=\"x89cf9b\"><strong>והתרגום?<\/strong> בשורה האחרונה, בגוף מאמר מהר״ש ובלשון של הצעה: <span class=\"qt cite\" data-ex=\"MH627-18\" data-n=\"VY02:MH-627\">״ולפי׳ התרגום שפי׳ ארי גלי קדמי, צ״ל לשון למען כנ״ל, ואפ״ל אף כי גליא קדמי אעפ״כ הידיעה אינה מכרחת הבחירה כו׳״<\/span> (כב). כלומר: הקב״ה יודע מראש, ועדיין אברהם בוחר. המו״ל מפנה כאן (<span class=\"qt\">״ראה״<\/span>) לאור התורה פט, א, <span class=\"qt cite\" data-ex=\"MH627-19\" data-n=\"VY02:MH-627\">״בשם הפנים יפות להרה״ק ר׳ פינחס בעל ההפלאה״<\/span>, ומעתיק משם: <span class=\"qt cite\" data-ex=\"MH627-19\" data-n=\"VY02:MH-627\">״דתיבת למען הוא שלא נאמר שהידיעה גורמת הבחירה... ונהפוך הוא אשר הבחירה דהיינו הציווי אשר יצוה היא גורמת הידיעה״<\/span> (הערה בע׳ כב). הבחירה כבר מתועדת אפוא באור התורה בשם הפנים יפות; אצל מהר״ש היא מובאת בגוף המאמר ומנוסחת בלשון <span class=\"qt\">״ואפ״ל״<\/span>.<\/p>\n<p id=\"xcbe7ed\"><strong>תרל״ד.<\/strong> אותו מאמר נאמר שוב בשבת פרשת וירא תרל״ד (כותרתו: <span class=\"qt\">״ש״פ וירא״<\/span>). המו״ל: <span class=\"qt cite\" data-ex=\"MH634-2\" data-n=\"VY02:MH-634\">״הוא ד״ה זה דשנת תרכ״ז [סה״מ תרכ״ז ע׳ כב ואילך, בכמה שינויים קלים אשר יצויינו להלן בשוה״ג]״<\/span> (מז, הערה 1). השינויים שבדקנו אכן קלים — למשל <span class=\"qt cite\" data-ex=\"MH634-3\" data-n=\"VY02:MH-634\">״לא יוצלח לשון למען הנכתב אחריו: בסה״מ תרכ״ז שם: אין למען נופל על הלשון״<\/span> (הערה 4) — והסיום כמעט זהה (<span class=\"qt\">״אפ״ל״<\/span>, בלי ו׳ החיבור). מה שמיוחד לתרל״ד הוא מה שבא מיד אחריו באותו עמוד: המאמר שאמר מהר״ש בבר המצוה של בנו, הרש״ב (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%98\" title=\"ט. כ׳ מרחשון בגשרים: בר מצוה, ״כמעט בכל שנה ושנה״, וחינוך\">פרק ט<\/a>).<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ג\" id=\"ch-ג\"><div class=\"part-head\"><h2 id=\"h-ch-ג\">ג. הרש״ב, תרס״ו: בלשון <span class=\"qt\">״וי״ל״<\/span> — <span class=\"qt\">״ידיעה״<\/span> היא הרצון, <span class=\"qt\">״חיבה״<\/span> היא התענוג<\/h2><\/div>\n<p id=\"xc12eb4\"><em>בשבת וירא תרס״ו — שלפי כותרת העמודים של המהדורה ולפי הרבי חלה בכ׳ מרחשון — הרש״ב שואל <span class=\"qt cite\" data-ex=\"RS666-2\" data-n=\"VY02:RS-666\">״מהו ההפרש ביניהם ברוחניות״<\/span>. תשובתו, בלשון <span class=\"qt\">״וי״ל״<\/span>: שני הפירושים הם שני כוחות בנפש ובמצוות — רצון גלוי ותענוג נעלם.<\/em><\/p>\n<p id=\"x210075\"><strong>היום.<\/strong> בשורת הכותרת של המאמר כתוב רק <span class=\"qt cite\" data-ex=\"RS666-1\" data-n=\"VY02:RS-666\">״בס״ד, ש״פ וירא, רס״ו״<\/span>. בכותרת העמודים של המהדורה כתוב <span class=\"qt cite\" data-ex=\"RS666-4\" data-n=\"VY02:RS-666\">״ש״פ וירא, כ״ף מרחשון, ה׳תרס״ו״<\/span>. והרבי, בתשל״ז, כותב: <span class=\"qt cite\" data-ex=\"RB737-17\" data-n=\"VY02:RB-737\">״להעיר שהקביעות דיום ההולדת (כ׳ מרחשון) בשנת תרס״ו היתה בש״ק פ׳ וירא אליו הוי׳ – גילוי מלמעלה״<\/span> (הערה 42).<\/p>\n<p id=\"xac0b65\"><strong>השאלה.<\/strong> הרש״ב שואל, כמו מהר״ש <strong><span class=\"smark\">[סינתזה]<\/span><\/strong>, על <span class=\"qt\">״למען״<\/span>, ומוסיף שאלה: <span class=\"qt cite\" data-ex=\"RS666-2\" data-n=\"VY02:RS-666\">״וצ״ל דבאמת לפי התרגום תי׳ למען אין לו פי׳ כלל, ואיך מפרש כי ידעתיו לשון ידיעה. וגם צ״ל בפי׳ התרגום ופי׳ רש״י שמפרשים לשון ידיעה ולשון חיבה, מהו ההפרש ביניהם ברוחניות, ומהו ענין החיבה״<\/span> (צא). המו״ל כותב שהמאמר <span class=\"qt cite\" data-ex=\"RS666-3\" data-n=\"VY02:RS-666\">״מיוסד על ד״ה ובבואה לפני המלך במאמרי אדמו״ר האמצעי״<\/span>; <span class=\"qt\">״להתחלת וסיום המאמר״<\/span> — כלומר (<span class=\"edn\">הערת המהדורה<\/span>) לפירושים שבראש המאמר ובסופו — הוא מפנה למהר״ש תרכ״ז ותרל״ד ולפר״ת (הערה 1). את המאמר ההוא לא קראנו.<\/p>\n<p id=\"x610a6b\"><strong>רצון ותענוג.<\/strong> רוב המאמר מוקדש לשני כוחות בנפש. לרצון יש תוקף: <span class=\"qt cite\" data-ex=\"RS666-7\" data-n=\"VY02:RS-666\">״שיש בכח הרצון לעלות בעילוי אחר עילוי כ״כ בעצם הנפש ממש, שאין כח זה בתענוג כלל״<\/span> (צה). ובכל זאת התענוג פנימי יותר: <span class=\"qt cite\" data-ex=\"RS666-8\" data-n=\"VY02:RS-666\">״אין זה מפני שהרצון הוא למעלה מהעונג בעצם הנפש... ואדרבה, העונג הוא בעצם הנפש בבחי׳ פנימיות יותר״<\/span> (צו). ההבדל ביניהם הוא בגילוי: <span class=\"qt cite\" data-ex=\"RS666-9\" data-n=\"VY02:RS-666\">״דברצון, גם בחי׳ הרצון העצמי מתפשט ומתגלה כמו שהוא, ובתענוג, מה שמתפשט ומתגלה הוא בחי׳ הארת העונג, אבל העונג העצמי אינו מתפשט ומתגלה כו׳״<\/span> (צז).<\/p>\n<p id=\"x1eed99\"><strong>האב והבן.<\/strong> כדי להראות שהרצון <span class=\"qt\">״תופס בעצם המהות״<\/span> הרש״ב מביא משל שמתאים לפסוק שלנו: <span class=\"qt cite\" data-ex=\"RS666-10\" data-n=\"VY02:RS-666\">״וכן הוא באהבת האב אל הבן, שרוצה בעצם מהות הבן דוקא... דגם כשהבן אינו כדבעי ח״ו, שאינו הולך בדרך הישר ר״ל, ומ״מ, האב רוצה בו בעצם... דמצד התענוג בודאי אינו מתענג בו כלל, ואדרבא, הוא מצטער מהנהגתו הלא טובה כו׳, אבל מצד הרצון ה״ה רוצה בו כו׳״<\/span> (צח). ובדוגמה זו — אהבת הקב״ה לישראל <span class=\"qt cite\" data-ex=\"RS666-19\" data-n=\"VY02:RS-666\">״גם אם אינם כדבעי״<\/span>. <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> המאמר עצמו אינו מקשר את המשל ל״יצוה את בניו״; אנחנו מציינים את הסמיכות.<\/p>\n<p id=\"x3d941f\"><strong>מים רבים.<\/strong> והרצון העצמי של יהודי אינו משתנה: <span class=\"qt cite\" data-ex=\"RS666-5\" data-n=\"VY02:RS-666\">״לא ישונה כלל גם אם נשקע ח״ו בריבוי תענוגים גשמיים״<\/span>, <span class=\"qt cite\" data-ex=\"RS666-6\" data-n=\"VY02:RS-666\">״וכמ״ש מים רבים לא יוכלו לכבות את האהבה, דמים רבים הן ריבוי התענוגים הגשמי׳, לא יוכלו לכבות את האהבה דכנס״י להקב״ה כו׳״<\/span> (צג).<\/p>\n<p id=\"xe8c1bf\"><strong>המצוות.<\/strong> מכאן לפסוק. הרצון שבמצוות הוא <span class=\"qt cite\" data-ex=\"RS666-11\" data-n=\"VY02:RS-666\">״רצון העצמי דפנימיות ועצמות א״ס ב״ה, שאינו מורכב בשום דבר, והוא במעשה המצות בפו״מ דוקא, ואין טעם לרצון זה כלל״<\/span> (קא). ובו גנוז גם תענוג: <span class=\"qt cite\" data-ex=\"RS666-12\" data-n=\"VY02:RS-666\">״ומה שבא בהתגלות עכשיו הוא בחי׳ הרצון בלבד, ולעתיד יתגלה בחי׳ התענוג העצמי שברצון דמעהמ״צ״<\/span> (קב).<\/p>\n<p id=\"x422e09\"><strong>ושני הפירושים.<\/strong> <span class=\"qt cite\" data-ex=\"RS666-13\" data-n=\"VY02:RS-666\">״וע״פ הנ״ל יובן מ״ש כי ידעתיו למען אשר יצוה, דפירש״י לשון חיבה, והיינו בחי׳ תענוג העצמי שנמשך ע״י המצות בפו״מ... למען אשר יצוה כו׳ לעשות צדקה ומשפט, והיינו קיום המצות בפו״מ בבחי׳ קבעומ״ש״<\/span> (קב). והתרגום — <span class=\"qt cite\" data-ex=\"RS666-14\" data-n=\"VY02:RS-666\">״שהידיעה אינו מכרחת את הבחירה, דאעפ״י שגלי קדמי, מ״מ, הבחירה חפשית, והיינו שהידיעה היא כמו שיהי׳ אחר הבחירה כו׳״<\/span> (קב–קג). ולבסוף, בלשון <span class=\"qt\">״וי״ל״<\/span>: <span class=\"qt cite\" data-ex=\"RS666-15\" data-n=\"VY02:RS-666\">״וי״ל דמה שהתרגום מפרש ל׳ ידיעה, ורש״י פי׳ לשון חיבה, הוא ההפרש בין בחי׳ רצון העצמי ובחי׳ עונג העצמי״<\/span> (קג). התרגום — <span class=\"qt\">״ארי גלי קדמי״<\/span> — הוא הרצון, שגלוי כבר עכשיו; רש״י — החיבה — הוא התענוג, <span class=\"qt cite\" data-ex=\"RS666-16\" data-n=\"VY02:RS-666\">״שהרי ג״ז נמשך ע״י עשיות המצות בפו״מ דעכשיו, אלא שהגילוי יהי׳ לעתיד״<\/span> (קג).<\/p>\n<aside class=\"synth\"><p id=\"xb75924\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> מהר״ש פירש <span class=\"qt\">״חיבה״<\/span> דרך משל העודר, והביא את הבחירה כהצעה אחרונה; הרש״ב משאיר את שניהם, ומוסיף להם שכבה: שני הפירושים הם שתי דרגות במה שהמצוות ממשיכות. המו״ל, בהערה 125, מביא שוב את לשון הפנים יפות, ומוסיף: <span class=\"qt cite\" data-ex=\"RS666-17\" data-n=\"VY02:RS-666\">״הטעם שמביא זה בהמאמר דתרס״ו, נת׳ בסד״ה כי ידעתיו תשל״ו״<\/span> — ולשם נגיע ב<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%96\" title=\"ז. הרבי, תשל״ו: הרצון נותן כוח, והבחירה נשארת שלו\">פרק ז<\/a>.<\/p><\/aside>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ד\" id=\"ch-ד\"><div class=\"part-head\"><h2 id=\"h-ch-ד\">ד. הרש״ב, תרס״ז: <span class=\"qt\">״דרך ה׳״<\/span> מלמעלה, <span class=\"qt\">״צדקה ומשפט״<\/span> מלמטה<\/h2><\/div>\n<p id=\"x80f0b8\"><em>שנה אחר כך, בשבת וירא שחלה, לפי כותרת העמודים, <span class=\"qt\">״ט״ו מרחשון״<\/span>, הרש״ב פותח בפסוק שלפני <span class=\"qt\">״כי ידעתיו״<\/span>, ושואל את שאלת הכפל: אם דרך ה׳ היא התורה והמצוות, מה מוסיפים צדקה ומשפט? תשובתו: שני כיוונים.<\/em><\/p>\n<p id=\"x6c26d3\"><strong>השאלה.<\/strong> <span class=\"qt cite\" data-ex=\"RS667-1\" data-n=\"VY02:RS-667\">״וה׳ אמר המכסה אני מאברהם כו׳ ואברהם היו יהי׳ לגוי גדול כו׳ כי ידעתיו... וצ״ל, מה״ע המכסה אני. גם צ״ל מ״ש ושמרו דרך ה׳ לעשות צדקה ומשפט, הלא דרך ה׳ זהו תומ״צ, וא״כ, מה צ״ל צדקה ומשפט״<\/span> (תקכה). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> זו כמעט שאלת תורת חיים (<span class=\"qt cite\" data-ex=\"MZTC-1\" data-n=\"VY02:MZ-TC\">״שמירה בדרך הוי׳ ועשי׳ בצדקה״<\/span>); המו״ל אומר שהמאמר <span class=\"qt cite\" data-ex=\"RS667-7\" data-n=\"VY02:RS-667\">״מיוסד על: ד״ה ויקהל בתו״ח שמות ח״ב״<\/span> ועל מאמר של אדמו״ר האמצעי בדרושי חתונה (הערה 1) — לא על הביאור שקראנו.<\/p>\n<p id=\"x692fba\"><strong>שני בירורים, ומשל האב והתינוק.<\/strong> <span class=\"qt cite\" data-ex=\"RS667-2\" data-n=\"VY02:RS-667\">״ולהבין כ״ז צלה״ק משנת״ל שיש ב׳ מיני בירורים. הא׳, בירור דאו״י שמלמעלה למטה, והב׳, בירור דאו״ח מלמטה למעלה״<\/span> (תקכה). (<span class=\"edn\">הערת המהדורה<\/span>: אור ישר ואור חוזר — השפעה שיורדת מלמעלה, ועבודה שעולה מלמטה.) וגם בבירור שמלמטה יש עזר נסתר מלמעלה: <span class=\"qt cite\" data-ex=\"RS667-3\" data-n=\"VY02:RS-667\">״ויובן זה עד״מ כמו התינוק הקטן שא״י לילך מכח עצמו, כ״א ע״י הגדול, כאביו, שעומד מאחוריו ואוחזו ומוליכו או דוחפו מאחוריו, שמכח זה ילך, ועצם ההילוך הוא שהולך בעצמו״<\/span> (תקכה). ויש עזר גלוי: <span class=\"qt cite\" data-ex=\"RS667-4\" data-n=\"VY02:RS-667\">״או שאם קטן הוא ביותר שא״י לעמוד על רגליו כלל, ויגב[י]הנו האב על כתפו וישאנו כאשר ישא האומן את היונק כו׳, שאז צריך האב להשפיל למקום הנמוך ל[ה]עלות את בנו על כתפו״<\/span> (תקכז). ומשל שני — רב שמלמד את תלמידו: <span class=\"qt cite\" data-ex=\"RS667-6\" data-n=\"VY02:RS-667\">״לעולם ישנה אדם לתלמידו בדרך קצרה״<\/span> (תקכח), והתלמיד חושב שהבין לבד.<\/p>\n<p id=\"x19eb37\"><strong>התשובה.<\/strong> בסוף המאמר: <span class=\"qt cite\" data-ex=\"RS667-10\" data-n=\"VY02:RS-667\">״וז״ש כי ידעתיו למען אשר יצוה, פי׳ כי ידעתיו ל׳ חיבה, שחיבב אותו בבחי׳ תענוג העצמי דעצמות א״ס ממש כו׳, והיינו בשביל אשר יצוה כו׳ ושמרו דרך ה׳ לעשות צדקה ומשפט, פי׳ דרך ה׳ היינו בבחי׳ המשכה מלמעלה למטה, וזהו אופן ההמשכה דתושב״כ. וענין צדקה ומשפט זהו העבודה בבחי׳ מלמטה למעלה״<\/span> (תקלז). ו״המכסה אני״ — <span class=\"qt cite\" data-ex=\"RS667-10\" data-n=\"VY02:RS-667\">״בחי׳ העלם העצמי דא״ס, שנתגלה לאברהם... וזהו ע״י הנסיונות שלו״<\/span>. והמשפט האחרון: <span class=\"qt cite\" data-ex=\"RS667-11\" data-n=\"VY02:RS-667\">״וכ״ז הוא למען אשר יצוה כו׳, ושמרו דרך ה׳ לעשות צדקה ומשפט, שזהו העבודה ביגיעה מלמטה למעלה דוקא, שעי״ז דוקא נמשך גילוי בחי׳ העצמות כו׳״<\/span> (תקלז).<\/p>\n<aside class=\"synth\"><p id=\"x19c21a\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> בתרס״ו שני פירושים ל״ידעתיו״; כאן רק <span class=\"qt\">״חיבה״<\/span>. בתרס״ו צדקה ומשפט הן קיום המצוות בקבלת עול; כאן הן כיוון בפני עצמו, מלמטה, מול <span class=\"qt\">״דרך ה׳״<\/span> שמלמעלה. את ההבדל הזה ינסח הרבי במפורש (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%97\" title=\"ח. הרבי, תשל״ז: שני המאמרים של הרש״ב, ו״אשר יצוה את בניו״ כנתינת כוח לכל אחד מישראל\">פרק ח<\/a>). המו״ל של תרס״ו כותב בהערה 1 ש־״התחלת וסיום המאמר נתבאר בארוכה בד״ה זה תשל״ז״, ומוסיף שם (הערה *): <span class=\"qt cite\" data-ex=\"RS667-8\" data-n=\"VY02:RS-667\">״שם נת׳ גם ההפרש בין מאמר זה (שהוא מאמר הב׳ דפ׳ וירא בהמשך תרס״ו) לבין ד״ה כי ידעתיו תרס״ו״<\/span>.<\/p><\/aside>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ה\" id=\"ch-ה\"><div class=\"part-head\"><h2 id=\"h-ch-ה\">ה. הרש״ב, פר״ת: מאמר מהר״ש עם <span class=\"qt\">״תוס׳ ביאור והוספות״<\/span> — משפיע ומקבל, רחמי המלך, ונימוק לבחירה<\/h2><\/div>\n<p id=\"xbe0d85\"><em>לפי המו״ל בתרכ״ז זהו מאמר מהר״ש <span class=\"qt\">״בתוס׳ ביאור והוספות״<\/span>; לפי השוואתנו המבנה נשמר כמעט סעיף אחר סעיף. המאמר מבאר ומעמיק את תכלית הדירה בתחתונים, שכבר מפורשת בהנחות תקע״ז, עד <span class=\"qt\">״פנימיות ועצמות א״ס״<\/span> וכללות ההמשכה בצדקה ומשפט; ונוספים בו נימוק למשפיע ומקבל, פירוש מורחב ל״עליו״ ונימוק ל״למען״ — <span class=\"qt\">״כן פי׳ הפנ״י״<\/span>.<\/em><\/p>\n<p id=\"x41d340\"><strong>הכותרת: <span class=\"qt cite\" data-ex=\"RS680-1\" data-n=\"VY02:RS-680\">״בס״ד ש״פ וירא, פר״ת.״<\/span><\/strong> (קלב). השאלות מורחבות: <span class=\"qt cite\" data-ex=\"RS680-2\" data-n=\"VY02:RS-680\">״למה נא׳ צדקה ומשפט הרי יש כמה ענינים בתורה כו׳. גם מ״ש למען הביא כו׳ את אשר דבר עליו צ״ל מהו אשר דבר עליו ולכאו׳ הול״ל אשר דבר לו מהו עליו כו׳״<\/span> (קלג). ובעניין דוד, הגהה בסוגריים: <span class=\"qt cite\" data-ex=\"MH627-23\" data-n=\"VY02:MH-627\">״(וצ״ע בכוונת רש״י שם)״<\/span> (קלג). גם המו״ל של תרכ״ז מציין: <span class=\"qt cite\" data-ex=\"MH627-23\" data-n=\"VY02:MH-627\">״בד״ה זה פר״ת נוספה כאן הגהה: ״וצ״ע בכוונת רש״י שם״<\/span>״.<\/p>\n<p id=\"x1d682e\"><strong>משפיע ומקבל.<\/strong> לשאלת מהר״ש — למה עניים ועשירים, שאצלו נענתה בשמש ובלבנה — מצטרפת כאן תשובה נוספת: <span class=\"qt cite\" data-ex=\"RS680-5\" data-n=\"VY02:RS-680\">״וזהו שנבראו עניים ועשירים מפני שתכלית הכוונה בברה״ע הוא לא רק בשביל האור והגילוי שמאיר בעולמות כ״א להיות תוס׳ אור מבחי׳ עצמות א״ס וזה נמשך דוקא כאשר יש משפיע שהעשיר משפיע לעני כו׳״<\/span> (קלו). תכלית הדירה בתחתונים כבר מפורשת בהנחות תקע״ז, ע׳ סג; פר״ת מעמיק אותה בהמשכת פנימיות ועצמות א״ס ומעמיד את צדקה ומשפט ככללות הדרך לכך. ומן הגמרא: <span class=\"qt cite\" data-ex=\"RS680-4\" data-n=\"VY02:RS-680\">״רש ואיש תככים נפגשו מאיר עיני שניהם ה׳, דכאשר העשיר מפרנס את העני אזי מאיר עיני שניהם ה׳, ושם גם בענין ההשפעה שכאשר הרב משפיע להתלמיד מאיר עיני שניהם ה׳ עיני הרב ועיני התלמיד כו׳״<\/span> (קלו).<\/p>\n<p id=\"x5e8196\"><strong>רחמי המלך.<\/strong> ובעניין הצדקה, שני מיני רחמים: מי שמרגיש את הזולת, ומי שרחמיו באים <span class=\"qt cite\" data-ex=\"RS680-6\" data-n=\"VY02:RS-680\">״מצד הרוממות שהוא ענין טבעי שטבע המרומם להיות נמשך אל השפל... וכמו רחמי המלך שמרובים מרחמי השר״<\/span> (קלז). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> אותו משל — <span class=\"qt\">״מלך המתנשא״<\/span> מול <span class=\"qt\">״שר״<\/span> — אצל אדמו״ר האמצעי: בהנחות תקע״ז ובתורת חיים (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%90\" title=\"א. השורש: צדקה ומשפט הם ״דרך כלל״ כל המצוות, והמשפט הוא גבול לתענוגות\">פרק א<\/a>), וגם באשירה (קיד). לא מצאנו בפר״ת הפניה אליהם.<\/p>\n<p id=\"x6ee343\"><strong>המשפט שבצדקה.<\/strong> כיוון שהצדקה ממשיכה מלמעלה גם <span class=\"qt\">״במקום שאינו ראוי״<\/span>, <span class=\"qt cite\" data-ex=\"RS680-7\" data-n=\"VY02:RS-680\">״ע״ז הוא המשפט שיומשך למקום הראוי דוקא, ומה שאינו ראוי יהי׳ נדחה״<\/span> (קלח). ו״עליו״ — <span class=\"qt cite\" data-ex=\"RS680-8\" data-n=\"VY02:RS-680\">״שלמעלה ממנו ושהוא כלי לזה״<\/span> (קלט).<\/p>\n<p id=\"x1aaa48\"><strong>החיבה והבחירה.<\/strong> <span class=\"qt cite\" data-ex=\"RS680-9\" data-n=\"VY02:RS-680\">״וז״ע החיבה היינו המשכת בחי׳ עצמות א״ס בחי׳ טוב ה׳ לקויו וזהו שנמשך לאברהם משום ושמרו דרך ה׳ לעשות צדקה ומשפט שהמשיך בחי׳ הפנימיות כו׳״<\/span> (קמ). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> ומה שאצל מהר״ש היה <span class=\"qt\">״ואפ״ל״<\/span>, כאן מנומק, עם שם המקור: <span class=\"qt cite\" data-ex=\"RS680-10\" data-n=\"VY02:RS-680\">״הענין הוא שזהו שהידיעה אינה מכרחת את הבחירה (כן פי׳ הפנ״י) שהגם שידוע למעלה מ״מ אברהם עשה זה בבחירתו, ועז״א למען אשר יצוה, שאם הי׳ או׳ כי ידעתיו אשר יצוה הי׳ משמע שע״י הידיעה הי׳ עשי׳ בדרך ממילא עז״א למען אשר יצוה להודיע שאברהם עשה כן בבחירת עצמו כו׳״<\/span> (קמ). והסיום: <span class=\"qt cite\" data-ex=\"RS680-11\" data-n=\"VY02:RS-680\">״דתכלית הכוונה בבריאת והתהוות העולם הוא להמשיך בחי׳ פנימיות ועצמות א״ס ע״י תומ״צ וכללותם הוא צדקה ומשפט״<\/span> (קמ).<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ו\" id=\"ch-ו\"><div class=\"part-head\"><h2 id=\"h-ch-ו\">ו. הריי״צ: למה החיבה תלויה ב״יצוה״, ומה פירוש <span class=\"qt\">״יצוה״<\/span><\/h2><\/div>\n<p id=\"x7cab14\"><em>בתרפ״ד הריי״צ שואל על רש״י: אחרי כל גדולת אברהם, למה החיבה תלויה דווקא בכך שהוא מצווה את בניו? בתש״ז הוא קורא <span class=\"qt\">״יצוה״<\/span> מלשון צוותא — חיבור.<\/em><\/p>\n<p id=\"xa51353\"><strong>תרפ״ד: הקושיה.<\/strong> <span class=\"qt cite\" data-ex=\"RY684-2\" data-n=\"VY02:RY-684\">״ופי׳ רש״י כי ידעתיו ל׳ חיבה... ולמה ידעתיו למען אשר יצוה לפי אשר יצוה את בניו עלי לשמור דרכי״<\/span> (פ). ועל זה: <span class=\"qt cite\" data-ex=\"RY684-3\" data-n=\"VY02:RY-684\">״וצ״ל והלא פשיטות משמעות הענין הוא דזה המשך מהקודם דאברהם היו יהי׳ לגוי גדול ועצום״<\/span>; ועוד: אברהם קיים את התורה <span class=\"qt cite\" data-ex=\"RY684-5\" data-n=\"VY02:RY-684\">״וכל עבודתו היתה בכח עצמו ובמס״נ ממש״<\/span>, <span class=\"qt cite\" data-ex=\"RY684-4\" data-n=\"VY02:RY-684\">״הנה אחרי כל ההפלאה הזאת אומר כי ידעתיו למה ידעתיו למה זכה אברהם לחבבו לפי אשר יצוה את בניו כו׳״<\/span> (פא).<\/p>\n<p id=\"x1e07be\"><strong>דרך הוי׳ — הגורם.<\/strong> והשאלה השנייה: <span class=\"qt cite\" data-ex=\"RY684-4\" data-n=\"VY02:RY-684\">״וצ״ל מהו״ע דרך הוי׳ דלאחר שאומר לעשות צדקה ומשפט שהם ענינים של פועל, ומהו דרך הוי׳, אלא המובן מזה הוא דיש דרך הוי׳ שזהו הגורם לעשות צדקה ומשפט, ולפי שאברהם יצוה לבניו שישמרו דרך הוי׳ לזאת ידעתיו בחיבה יתירה יותר מכל עבודתו במס״נ וריבוי נסיונות שנתנסה כו׳״<\/span> (פא). כלומר: מה שמחבב את אברהם יותר מכל נסיונותיו הוא מה שהוא מעביר הלאה. ומה שהוא מעביר הוא עבודה בעולם, בגלות ובתוך הטבע: <span class=\"qt cite\" data-ex=\"RY684-6\" data-n=\"VY02:RY-684\">״לכך אברהם מצוה לבניו אחריו שמרו דרך ה׳ שיהי׳ גילוי שם הוי׳... דגם בהטבע יהי׳ נראה וניכר הלמע׳ מדרך הטבע״<\/span> (פב).<\/p>\n<p id=\"x7b21fa\"><strong>המצוה — המחבר.<\/strong> והסיום: <span class=\"qt cite\" data-ex=\"RY684-9\" data-n=\"VY02:RY-684\">״וזהו כי ידעתיו כו׳ ושמרו דרך ה׳, יש דרך דע״י הוא גילוי שם הוי׳ בעולם, ואברהם הוא המצוה, כלומר המחבר שפועל בנש״י שהם בניו וביתו של אברהם אשר ישמרו דרך ה׳ בסוד הבירורים, ואז הנה ע״י הוא לעשות צדקה ומשפט שהם העבודה דתו׳ והעבודה דתפלה״<\/span> (צג). ולפני כן — הוראה מעשית <span class=\"qt cite\" data-ex=\"RY684-8\" data-n=\"VY02:RY-684\">״הן יושבי אהל והן בעלי עסקים״<\/span>: כשנדמה לאדם שעליו לצאת לעסקיו לפני התפילה, <span class=\"qt cite\" data-ex=\"RY684-8\" data-n=\"VY02:RY-684\">״הנה יהי׳ הסכם והחלט אצלו שלא ללכת״<\/span> (צג).<\/p>\n<p id=\"xd580c8\">על המאמר הזה כתוב במפתח הכרך, <span class=\"qt cite\" data-ex=\"RY684-11\" data-n=\"VY02:RY-684/מפתח\">״[הערת כ״ק אדמו״ר שליט״א]״<\/span>, ש״מתחלה נכתב כל ההמשך — מתחיל: נתת ליראיך נס — בקונטרס בפ״ע. ונתוספו עליו הגהות והתחלת וסוף כל מאמר: כי ידעתיו, ואברהם זקן, וכו׳<span class=\"qt cite\" data-ex=\"RY684-12\" data-n=\"VY02:RY-684/מפתח\">״; ובהמשך המפתח: ״כי ידעתיו: ראה רד״ה נתת ליראיך פר״ת (סה״מ פר״ת ע׳ קה), המשך יו״ט של ר״ה תרס״ו בתחלתו״<\/span>.<\/p>\n<p id=\"xbc6d05\"><strong>תרפ״ו.<\/strong> המאמר הבא של הריי״צ על הפסוק, בספר המאמרים תרפ״ו, רשום במפתח הכרך כך: <span class=\"qt cite\" data-ex=\"RY686-1\" data-n=\"VY02:RY-686\">״כי ידעתיו — וירא, כ׳ מ״ח — קא״<\/span>; ובהערה שם: <span class=\"qt cite\" data-ex=\"RY686-2\" data-n=\"VY02:RY-686\">״כ׳ מ״ח: יום הולדת אביו כ״ק אדמו״ר (מוהרש״ב) נ״ע [ראה ד״ה זה פר״ת״<\/span>. את המאמר עצמו לא קראנו.<\/p>\n<p id=\"xe4df0b\"><strong>תש״ז: צוותא.<\/strong> בש״פ וירא תש״ז (ולא בכ׳ מרחשון, לפי הכותרות: המאמר הבא בכרך כותרתו <span class=\"qt cite\" data-ex=\"RY707-6\" data-n=\"VY02:RY-707\">״בס״ד, ה׳ כ׳ מר״ח תש״ז״<\/span>) הריי״צ פותח בפירוש של מילה: <span class=\"qt cite\" data-ex=\"RY707-2\" data-n=\"VY02:RY-707\">״ולמה ידעתיו למען אשר יצוה לפי שהוא מצוה את בניו עלי לשמור דרכי, היינו תומ״צ, כי מצוה ל׳ צוותא והתקשרות, וזהו למען אשר יצוה התקשרות להמשיך אורו ית׳ בתחתונים, כי ע״י תומ״צ מזכך גופו ומקום מושבו, עד שנשלמה הכוונה העליונה שיהי׳ גילוי עצמות אוא״ס למטה״<\/span> (188). שאר המאמר עוסק במאמר חז״ל <span class=\"qt cite\" data-ex=\"RY707-3\" data-n=\"VY02:RY-707\">״אדם מקדש א״ע מעט מקדשין אותו הרבה״<\/span> — ההכנה הקטנה שמביאה סיוע גדול מלמעלה (188–190) — ובחסיד: <span class=\"qt cite\" data-ex=\"RY707-5\" data-n=\"VY02:RY-707\">״וזהו החסיד המתחסד עם קונו לתקן גופו ולזככו... וכן עם קן דילי׳ מקום מושבו להאירה באור התורה והעבודה״<\/span> (191).<\/p>\n<aside class=\"synth\"><p id=\"xd7cd2c\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> בתרפ״ד — <span class=\"qt\">״המצוה, כלומר המחבר״<\/span>; בתש״ז — <span class=\"qt cite\" data-ex=\"RY707-2\" data-n=\"VY02:RY-707\">״מצוה ל׳ צוותא והתקשרות״<\/span>. שני המאמרים קוראים את <span class=\"qt\">״יצוה״<\/span> כקשר, לא רק כפקודה. הריי״צ אינו מקשר ביניהם.<\/p><\/aside>\n<p id=\"xf4f444\"><strong><span class=\"qt\">״זה היום״<\/span>.<\/strong> בשני מאמרים לי״ב תמוז (תרפ״ח, תש״ח) הריי״צ חוזר על חלקים ממאמר מהר״ש — לפי המו״ל בתרכ״ז — והפסוק מופיע שם רק כדוגמה בתוך דרשת ר׳ שמלאי: <span class=\"qt cite\" data-ex=\"RY688-2\" data-n=\"VY02:RY-688\">״וזהו חזר ישעי׳ והעמידן על שתים כה אמר ה׳ שמרו משפט ועשו צדקה כו׳ וכמ״ש גבי אברהם כי ידעתיו למען אשר יצוה את בניו כו׳ לעשות צדקה ומשפט״<\/span> (תרפ״ח, ע׳ קנו). ובמשפט אחד שם יש תוספת על מהר״ש, שהמו״ל של תרכ״ז מציין (<span class=\"qt cite\" data-ex=\"MH627-22\" data-n=\"VY02:MH-627\">״בסה״מ תרפ״ח ותש״ח שם מוסיף כאן״<\/span>). בלשון תרפ״ח (קנד): <span class=\"qt cite\" data-ex=\"RY688-3\" data-n=\"VY02:RY-688\">״והנה קבלה לאבותינו רבותינו מרבינו הגדול אשר קבל מרבו ורבו מרבו דפי׳ זהיר ל׳ זוהר ואור״<\/span>.<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ז\" id=\"ch-ז\"><div class=\"part-head\"><h2 id=\"h-ch-ז\">ז. הרבי, תשל״ו: הרצון נותן כוח, והבחירה נשארת שלו<\/h2><\/div>\n<p id=\"x5eacae\"><em>בשבת וירא שחלה בכ׳ מרחשון תשל״ו, <span class=\"qt\">״כעין שיחה״<\/span>, הרבי פותח במה ש־״מביא ע״ז בעל יום ההולדת״ בתרס״ו, ומסביר, בלשון <span class=\"qt\">״ויש לומר״<\/span>, למה הרש״ב מביא שם את עניין הבחירה: כדי שהעבודה תהיה של האדם עצמו.<\/em><\/p>\n<p id=\"x7d2ff9\"><strong>הפתיחה.<\/strong> <span class=\"qt cite\" data-ex=\"RB736-1\" data-n=\"VY02:RB-736\">״כי ידעתיו... ומביא ע״ז בעל יום ההולדת כ״ק אדמו״ר (מהורש״ב) נ״ע בהמשך יום טוב של ראש השנה שחל להיות בשבת (כקביעות שנה זו) תרס״ו פירוש התרגום עה״פ, דכי ידעתיו היינו ארי גלי קדמי, ומבאר שהו״ע הרצון שהוא בגלוי (גלי קדמי), ופירש״י דכי ידעתיו הוא לשון חיבה״<\/span>. הכותרת בתוכן הספר: <span class=\"qt cite\" data-ex=\"RB736-0\" data-n=\"VY02:RB-736/כותרת\">״כי ידעתיו – ש״פ וירא, כ׳ מרחשון ה׳תשל״ו״<\/span>.<\/p>\n<p id=\"x2b5d99\"><strong>השאלה.<\/strong> <span class=\"qt cite\" data-ex=\"RB736-2\" data-n=\"VY02:RB-736\">״דלפירש״י מובן, דכי ידעתיו לשון חיבה למען (בשביל) אשר יצוה גו׳... משא״כ לפירוש התרגום דכי ידעתיו קאי על ענין הרצון, הרי תיבת למען אין לה פירוש כלל״<\/span>.<\/p>\n<p id=\"x94eefd\"><strong>מים רבים ומהר״ש.<\/strong> לפני התשובה הרבי עובר דרך מאמר אחר: יש לקשר את הכתוב, הוא אומר, <span class=\"qt cite\" data-ex=\"RB736-3\" data-n=\"VY02:RB-736\">״גם עם המאמר דבן מאה שנה (מש״פ וירא תרל״ו) מכ״ק אדמו״ר מהר״ש [שבעל יום ההולדת הי׳ ממלא מקומו]״<\/span>, על <span class=\"qt cite\" data-ex=\"RS666-6\" data-n=\"VY02:RS-666\">״מים רבים לא יוכלו לכבות את האהבה״<\/span>. שם — וכך גם, לפי הרבי, בתורה אור נח, שעליו <span class=\"qt\">״מיוסד כנראה״<\/span> מאמר תרל״ו — <span class=\"qt cite\" data-ex=\"RB736-4\" data-n=\"VY02:RB-736\">״המים רבים הם טרדות הפרנסה״<\/span>. (בתרס״ו, ראינו, <span class=\"qt\">״מים רבים״<\/span> הם <span class=\"qt\">״ריבוי התענוגים הגשמי׳״<\/span>.) אבל העיסוק בגשמיות אינו פסול: <span class=\"qt cite\" data-ex=\"RB736-6\" data-n=\"VY02:RB-736\">״והיינו שצ״ל ההתעסקות בדברים הגשמיים בשביל התורה ומצוות, וכדי שיהי׳ כל מעשיך לשם שמים״<\/span>. ולכך — סיפור הבעש״ט, שלימד זכות על בעלי בתי המרזח, <span class=\"qt cite\" data-ex=\"RB736-5\" data-n=\"VY02:RB-736\">״שעושים זאת כדי להשיא בתו לתלמיד חכם וכן לשכור מלמד לבנו״<\/span>.<\/p>\n<p id=\"x69a901\"><strong>התשובה.<\/strong> <span class=\"qt cite\" data-ex=\"RB736-7\" data-n=\"VY02:RB-736\">״שזה מובן ע״י ביאור הפסוק מים רבים כנ״ל״<\/span>, אומר הרבי; <span class=\"qt cite\" data-ex=\"RB736-7\" data-n=\"VY02:RB-736\">״דאיך אפשר להיות ושמרו דרך ה׳ גו׳, זהו ע״י כי ידעתיו שבפירוש התרגום קאי זה על בחי׳ הרצון, הרצון העצמי, עד להרצון שבעצמות. דעי״ז דוקא (למען אשר) יצוה את בניו וגו׳ עד סוף כל הדורות. וזה כולל גם הפירוש ביצוה מלשון צוותא וחיבור״<\/span>. ומיד הסייג: <span class=\"qt cite\" data-ex=\"RB736-8\" data-n=\"VY02:RB-736\">״אמנם אעפ״כ אין זה באופן דנהמא דכיסופא (שהרצון, ידעתיו, מכריח אותו), כי אם שנותנים לו את הכח ע״ז, ואח״כ פועל זאת בבחירתו. דזהו פירוש התרגום כי ידעתיו, ארי גלי קדמי... ולכן כתיב למען אשר יצוה (ולא ידעתיו אשר יצוה), כי הידיעה אינה מכרחת את הבחירה״<\/span>. (<span class=\"edn\">הערת המהדורה<\/span>: <span class=\"qt\">״נהמא דכיסופא״<\/span> — לחם של בושה, מה שאדם מקבל בלי שעבד עליו.)<\/p>\n<p id=\"x251df9\"><strong>למה תרס״ו מביא את הבחירה.<\/strong> ובלשון <span class=\"qt\">״ויש לומר״<\/span>: <span class=\"qt cite\" data-ex=\"RB736-9\" data-n=\"VY02:RB-736\">״ויש לומר שמביא שם (בתרס״ו) ענין זה (דהידיעה אינה מכרחת) כדי לבאר שאע״פ שהעבודה לברר את הענינים הגשמיים היא ע״י שהרצון העצמי הוא בגלוי (כנ״ל), הנה אעפ״כ אין זה נהמא דכיסופא״<\/span>. זה מה שהמו״ל של תרס״ו מפנה אליו (<span class=\"qt cite\" data-ex=\"RS666-17\" data-n=\"VY02:RS-666\">״הטעם שמביא זה בהמאמר דתרס״ו, נת׳ בסד״ה כי ידעתיו תשל״ו״<\/span>). והחיבה — <span class=\"qt cite\" data-ex=\"RB736-10\" data-n=\"VY02:RB-736\">״התענוג העצמי הנמשך ע״י מעשה התורה ומצוות... ועד שאין זה נהמא דכיסופא כי זוהי עבודתו (שלו), ואח״כ בא גם בגשמיות, וכמאמר כ״ק אדמו״ר הזקן שהקב״ה נותן לישראל גשמיות והם עושים מגשמיות רוחניות״<\/span>. סוף המאמר חסר: <span class=\"qt\">״חסר הסיום. המו״ל.״<\/span> (הערה 61).<\/p>\n<aside class=\"synth\"><p id=\"x8b1dc1\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> אצל מהר״ש הבחירה הייתה תשובה לשאלת לשון — <span class=\"qt\">״למען״<\/span>. אצל הרבי היא חלק מן התוכן: הכוח ניתן מלמעלה, <span class=\"qt\">״ידעתיו״<\/span>, אבל הבחירה והעבודה הן של האדם, ולכן הן שלו באמת. ו״יצוה את בניו״ — <span class=\"qt cite\" data-ex=\"RB736-7\" data-n=\"VY02:RB-736\">״עד סוף כל הדורות״<\/span>.<\/p><\/aside>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ח\" id=\"ch-ח\"><div class=\"part-head\"><h2 id=\"h-ch-ח\">ח. הרבי, תשל״ז: שני המאמרים של הרש״ב, ו״אשר יצוה את בניו״ כנתינת כוח לכל אחד מישראל<\/h2><\/div>\n<p id=\"xeaf1d9\"><em>שנה אחר כך, שוב בשבת וירא שחלה בכ׳ מרחשון, הרבי משווה במפורש בין שני המאמרים של <span class=\"qt\">״בעל יום ההולדת״<\/span> — הראשון והשני שבהמשך תרס״ו — מסביר מה פשר ההבדל ביניהם, ומעיר על הקביעות של היום בשתי השנים.<\/em><\/p>\n<p id=\"x1e4fe9\"><strong>הכותרת: <span class=\"qt cite\" data-ex=\"RB737-1\" data-n=\"VY02:RB-737\">״בס״ד. ש״פ וירא, כ״ף מרחשון ה׳תשל״ז״<\/span><\/strong> (רנה). המאמר מוגה: הוא נדפס בגוף <span class=\"qt\">״ספר המאמרים מלוקט״<\/span>, שלפי פתח הדבר שלו כולל את המאמרים <span class=\"qt cite\" data-ex=\"RB737-31\" data-n=\"VY02:RB-737/פתח דבר\">״אשר הוגהו על ידו״<\/span> (ולא ב״הוספות״, שבהן גוף המאמר <span class=\"qt\">״הנחה בלתי מוגה״<\/span>); ולפי הערה * <span class=\"qt cite\" data-ex=\"RB737-21\" data-n=\"VY02:RB-737\">״יצא לאור בקונטרס כ״ף מרחשון – תשמ״ז״<\/span>. המאמר פותח בשאלת תרס״ז: <span class=\"qt cite\" data-ex=\"RB737-1\" data-n=\"VY02:RB-737\">״ומדייק בזה בעל יום ההולדת במאמרו ד״ה זה דשנת תרס״ז (בהמשך תרס״ו), הרי דרך הוי׳ זהו תומ״צ, וא״כ מה מוסיף הכתוב בלעשות צדקה גו׳ (ענין המצוות) על ושמרו דרך הוי׳. ומבאר שם, דדרך הוי׳ היא המשכה מלמעלה למטה, וצדקה ומשפט היא העבודה בבחי׳ מלמטה למעלה, העבודה דאור חוזר״<\/span>.<\/p>\n<p id=\"x8ff31a\"><strong>שני מאמרים, שני פירושים.<\/strong> <span class=\"qt cite\" data-ex=\"RB737-2\" data-n=\"VY02:RB-737\">״והנה הפסוק כי ידעתיו גו׳ ושמרו דרך הוי׳ לעשות צדקה ומשפט נתבאר בהמשך הנ״ל בד״ה כי ידעתיו דשנת תרס״ו (מאמר דש״פ וירא הראשון שבההמשך), ובמאמר זה (מאמר דש״פ וירא השני שבההמשך״<\/span> — <span class=\"qt cite\" data-ex=\"RB737-2b\" data-n=\"VY02:RB-737/ספריית חב״ד\">״מבאר הפסוק באופן אחר״<\/span>. שני הבדלים. בפירוש <span class=\"qt\">״ידעתיו״<\/span>: <span class=\"qt cite\" data-ex=\"RB737-3\" data-n=\"VY02:RB-737\">״ומבאר שם דידעתיו לשון ידיעה הו״ע רצון העצמי... וידעתיו לשון חיבה הו״ע תענוג העצמי, משא״כ במאמר השני מפרש ידעתיו לשון חיבה, שחיבב אותו בבחי׳ תענוג העצמי״<\/span> (רנו). ובפירוש <span class=\"qt\">״לעשות צדקה ומשפט״<\/span>: <span class=\"qt cite\" data-ex=\"RB737-4\" data-n=\"VY02:RB-737\">״דבמאמר הראשון משמע... דלעשות צדקה ומשפט הוא הפירוש דושמרו דרך הוי׳, או שצדקה ומשפט הוא פרט בדרך הוי׳״<\/span>, <span class=\"qt cite\" data-ex=\"RB737-5\" data-n=\"VY02:RB-737\">״ובמאמר זה... מבאר דלעשות צדקה גו׳... הוא לא פירוש או פרט בדרך הוי׳ אלא שהוא ענין נוסף״<\/span> (רנו).<\/p>\n<p id=\"xf51e11\"><strong>הדרך: הליכה וחזרה.<\/strong> כדי להסביר, הרבי מביא מן ד״ה זכור תרע״ח של הרש״ב ומביאורי הזוהר של אדמו״ר האמצעי את משל הדרך: <span class=\"qt cite\" data-ex=\"RB737-6\" data-n=\"VY02:RB-737\">״דענין דרך למעלה הוא בדוגמת דרך כפשוטו (בגשמיות), שהוא ממוצע שמחבר שני מקומות שמצד עצמם הם רחוקים זמ״ז בתכלית״<\/span>. <span class=\"qt cite\" data-ex=\"RB737-7\" data-n=\"VY02:RB-737\">״וכמו דרך המלך הנמשך והולך מעיר המלוכה מקום מושב המלך לכל מרחבי המדינה... עד לפינה הכי נדחת״<\/span> (רנו). ודרך אמיתית <span class=\"qt cite\" data-ex=\"RB737-9\" data-n=\"VY02:RB-737\">״משמש לא רק להליכה אלא גם לחזרה״<\/span> (רנז): ההליכה היא ההמשכה מלמעלה — לימוד התורה; החזרה היא <span class=\"qt\">״העלאת התחתון״<\/span> — מעשה המצוות. <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> משל <span class=\"qt cite\" data-ex=\"AZH-1\" data-n=\"VY02:AZ-HOS\">״דרך הגשמי שבו עוברים ממקום למקום״<\/span>, בשני כיוונים, כבר ב״המכסה״ של אדמו״ר הזקן (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%90\" title=\"א. השורש: צדקה ומשפט הם ״דרך כלל״ כל המצוות, והמשפט הוא גבול לתענוגות\">פרק א<\/a>); הרבי אינו מפנה לשם.<\/p>\n<p id=\"x569220\"><strong>צדקה, משפט, לעשות.<\/strong> ומכאן כל מילה בפסוק: <span class=\"qt cite\" data-ex=\"RB737-10\" data-n=\"VY02:RB-737\">״ומוסיף צדקה ומשפט, דעשיית הצדקה (צדקה כפשוטה) צ״ל במשפט, שישפוט את עצמו מהמותרות ויחשוב היטב מה שהוא מוכרח לנפשו וכל השאר יתן לצדקה... ומוסיף לעשות (צדקה ומשפט), שגם זה... אינו מספיק עדיין, וצריך להיות באופן דאתכפיא, מעשה מלשון כפי׳״<\/span> (רנח). ובהערה 34 — <span class=\"qt cite\" data-ex=\"RB737-25\" data-n=\"VY02:RB-737\">״ראה גם תו״א בשלח סג, סע״ב״<\/span>. <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> כאן חוזר המשפט על המותרות של תורה אור — והפעם בהפניה מפורשת.<\/p>\n<p id=\"xaab3d1\"><strong>התוכן הפנימי של ההבדל.<\/strong> <span class=\"qt cite\" data-ex=\"RB737-11\" data-n=\"VY02:RB-737\">״ועפ״ז יש לבאר תוכן הפנימי של החילוקים דהמאמרים דש״פ וירא בהמשך תרס״ו. דבמאמר הראשון מבאר ענין המצוות, זה שע״י קיום המצוות נמשכים ענינים הכי נעלים, רצון עצמי ותענוג עצמי״<\/span> (רנט); <span class=\"qt cite\" data-ex=\"RB737-12\" data-n=\"VY02:RB-737\">״ולשנה הבאה במאמר השני מבאר העילוי דמעשה המצוות (עבודת המטה) כמו שהוא מצד עצמו, בדוגמת הגילוי דלעתיד שאז תתגלה מעלת המעשה, מעשה גדול״<\/span> (רנט). ולמה במאמר השני רק <span class=\"qt\">״חיבה״<\/span>? <span class=\"qt cite\" data-ex=\"RB737-14\" data-n=\"VY02:RB-737\">״[דגילוי תענוג העצמי הוא נעלה יותר מגילוי הרצון, שלכן גילוי הרצון יש גם עכשיו משא״כ גילוי התענוג יהי׳ רק לעתיד]״<\/span> (רס).<\/p>\n<p id=\"xa3bf1f\"><strong>הקביעות.<\/strong> וכאן הערה 42, על היום: <span class=\"qt cite\" data-ex=\"RB737-17\" data-n=\"VY02:RB-737\">״להעיר שהקביעות דיום ההולדת (כ׳ מרחשון) בשנת תרס״ו היתה בש״ק פ׳ וירא אליו הוי׳ – גילוי מלמעלה, והקביעות דיום ההולדת בשנת תרס״ז היתה ביום ה׳ פ׳ חיי שרה – כמה ימים דעבודה כמו שהיא לאחרי הגילוי מלמעלה״<\/span>. ובתוך ההערה: <span class=\"qt cite\" data-ex=\"RB737-20\" data-n=\"VY02:RB-737\">״להעיר שקביעות דכ׳ מרחשון (שהוא כמו הקביעות דיום א׳ דראש השנה) יכול להיות בד׳ ימים... וכשהקביעות דכ׳ מ״ח הוא ביום ה׳ – הוא ריבוי הכי גדול בימי העבודה שלאחרי הגילוי״<\/span> — הגילוי של וירא. ועוד: <span class=\"qt cite\" data-ex=\"RB737-18\" data-n=\"VY02:RB-737\">״ולהעיר גם מזה שבכל השנים (משנת תרנ״ד עד שנת תרע״ו) הי׳ אדמו״ר נ״ע בעל יום ההולדת בליובאַוויטש, מלבד בשנת תרס״ז שהי׳ אז בחו״ל, בוירצבורג... ואולי יש לומר, שגם ענין זה... שייך לעבודת הבירורים״<\/span>. ועל פרשת וירא עצמה — <span class=\"qt cite\" data-ex=\"RB737-19\" data-n=\"VY02:RB-737\">״שעוד בהיותו ילד השתוקק לזה ועד לבכי׳״<\/span> (הערה 42<em>). <\/em><em><span class=\"smark\">[סינתזה]<\/span><\/em>* כלומר, ההשוואה כאן היא בין שתי השנים תרס״ו ותרס״ז: הקביעות של היום בשתי השנים מתאימה לתוכן שני המאמרים — שבת וירא, <span class=\"qt\">״גילוי מלמעלה״<\/span>, למאמר על מה שהמצוות ממשיכות מלמעלה; ויום חמישי, ימי עבודה, למאמר על המעשה עצמו. ההערה אומרת זאת בלשון <span class=\"qt\">״להעיר״<\/span>; הלשון <span class=\"qt\">״ואולי יש לומר״<\/span> נאמרת בה על השהייה בוירצבורג.<\/p>\n<p id=\"x2b26e7\"><strong>אשר יצוה את בניו.<\/strong> והסוף, שבו הפסוק פונה אל כל אחד: <span class=\"qt cite\" data-ex=\"RB737-15\" data-n=\"VY02:RB-737\">״והנה שני ענינים אלו דושמרו דרך הוי׳ (המשכה מלמעלה למטה) לעשות צדקה ומשפט (עבודה מלמטה למעלה) ישנם בכאו״א מישראל, במשך כל הדורות. דנוסף על זה שכל עניני התורה הם נצחיים, ובפרט הענינים דמעשה אבות סימן ונתינת כח לבנים, הרי בנוגע לענין זה אומר בפירוש אשר יצוה את בניו ואת ביתו אחריו, עד סוף כל הדורות. וציווי זה (שאברהם מצוה את בניו גו׳) הוא נתינת כח מיוחד (נוסף על הנתינת כח שמצד מעשה אבות) לכל אחד מישראל על שתי עבודות הנ״ל״<\/span> (רס). ומשם למזמורי תהלים של בעל יום ההולדת — קטז, <span class=\"qt cite\" data-ex=\"RB737-16\" data-n=\"VY02:RB-737\">״אתהלך לפני הוי׳ בארצות החיים״<\/span>, וקיז — ולסיום: <span class=\"qt cite\" data-ex=\"RB737-30\" data-n=\"VY02:RB-737\">״שאז יתגלה העילוי דהעלאת התחתון, מעשה גדול, בביאת משיח צדקנו במהרה בימינו ממש״<\/span> (רסא).<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-ט\" id=\"ch-ט\"><div class=\"part-head\"><h2 id=\"h-ch-ט\">ט. כ׳ מרחשון בגשרים: בר מצוה, <span class=\"qt cite\" data-ex=\"RY692-3\" data-n=\"VY02:RY-692\">״כמעט בכל שנה ושנה״<\/span>, וחינוך<\/h2><\/div>\n<p id=\"xe4b5d9\"><em>שלושה טקסטים שאינם על הפסוק כפשוטו, אבל המקור עצמו קושר אותם ליום. בשניים מהם מופיע אב שמלמד את בנו, ובשלישי הפסוק מתפרש כחינוך.<\/em><\/p>\n<p id=\"xefc763\"><strong>מהר״ש, תרל״ד: מאמר בר המצוה.<\/strong> מיד אחרי <span class=\"qt\">״כי ידעתיו״<\/span> של ש״פ וירא תרל״ד בא בכרך מאמר על תפילין: <span class=\"qt cite\" data-ex=\"M634B-1\" data-n=\"VY02:MH-634B\">״איתא במדרש תילים ר׳ אליעזר אומר אמרו ישראל לפני הקב״ה רבש״ע רוצין אנו ליגע בתורה יומם ולילה אבל אין לנו פנאי א״ל הקב״ה קיימו מצות תפילין ומעלה אני עליכם כאלו אתם יגיעים בתורה יומם ולילה״<\/span> (נג). המו״ל: <span class=\"qt cite\" data-ex=\"M634B-3\" data-n=\"VY02:MH-634B\">״נאמר על בר מצוה של בנו אדמו״ר מהורש״ב נ״ע — ביום כ׳ מר־חשון תרל״ד״<\/span>; ובמפתח הכרך, בטור זמן האמירה: <span class=\"qt cite\" data-ex=\"M634B-3\" data-n=\"VY02:MH-634B\">״בר מצוה של בנו אדמו״ר מהורש״ב נ״ע״<\/span>. ועוד מוסיף המו״ל, בסוגריים: <span class=\"qt cite\" data-ex=\"M634B-3\" data-n=\"VY02:MH-634B\">״וע״ש אשר מאמר זה חזר אותו ג״כ כ״ק אדמו״ר מהוריי״צ נ״ע בחגיגת הבר מצוה שלו (ביום יב תמוז תרנ״ג)״<\/span>. ובהערה 6 מובאים דברי הריי״צ, שכשלמד את המאמר בעל פה התקשה בשינוי מלשון הכתוב: <span class=\"qt cite\" data-ex=\"M634B-5\" data-n=\"VY02:MH-634B\">״שאלתי את כ״ק אאמו״ר וענני״<\/span>. בגוף המאמר: <span class=\"qt cite\" data-ex=\"M634B-2\" data-n=\"VY02:MH-634B\">״יש מי שהוא מצוה לאחרים לעשות והוא אינו עושה אבל הקב״ה מה שהוא עושה אומר לישראל לעשות״<\/span> (נג). <strong><span class=\"smark\">[סינתזה]<\/span><\/strong> המאמר אינו מזכיר את פסוקנו. אנחנו מציינים שבכרך הוא בא אחרי מאמר כי ידעתיו, ושלפי המו״ל נאמר בבר המצוה של הבן, והריי״צ חזר עליו בבר המצוה שלו.<\/p>\n<p id=\"x7b0633\"><strong>הריי״צ, תרצ״ב: <span class=\"qt\">״כי נר מצוה״<\/span>.<\/strong> הכותרת: <span class=\"qt cite\" data-ex=\"RY692-1\" data-n=\"VY02:RY-692\">״בס״ד. ש״פ וירא, כ׳ מ״ח צב״ר, ריגא.״<\/span> המאמר מביא את פסוקנו בפתיחה כראיה: <span class=\"qt cite\" data-ex=\"RY692-2\" data-n=\"VY02:RY-692\">״והנה תומ״צ הם דרכי הוי׳ וכמ״ש כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך הוי׳ לעשות צדקה ומשפט וגו׳, דתורה ומצות הם דרכי הוי׳ שהם דרכי חיים, וא״כ מהו אומרו ודרך חיים״<\/span> (קכ). ובהערה 1 (מי כתב אותה — לא הוכרע; בהערה כתוב <span class=\"qt\">״שכ״ק מו״ח אדמו״ר״<\/span>) מובא מן הרשימות של אותו מוצאי שבת, שהריי״צ <span class=\"qt cite\" data-ex=\"RY692-3\" data-n=\"VY02:RY-692\">״אמר: היום חפצתי לדבר דא״ח – אמר דא״ח ד״ה כי נר מצוה – כי כמעט בכל שנה ושנה הייתי שומע דא״ח מאדמו״ר נ״ע ביום זה, שהוא יום הולדת את אדמו״ר נ״ע״<\/span>. ולפי הערה 2, המאמר <span class=\"qt cite\" data-ex=\"RY692-4\" data-n=\"VY02:RY-692\">״הוא ד״ה כי נר מצוה תרנ״ג... עם שינויים והוספות״<\/span> (<span class=\"edn\">הערת המהדורה<\/span>: ספר המאמרים תרנ״ג הוא של אדמו״ר הרש״ב).<\/p>\n<p id=\"x925286\"><strong>הרבי, תשמ״ז: שיחה על חינוך.<\/strong> <span class=\"qt cite\" data-ex=\"RB747-0\" data-n=\"VY02:RB-747S/ע׳ 494\">״בס״ד. משיחות ש״פ וירא, כ״ף מרחשון ה׳תשמ״ז.״<\/span> השיחה פותחת ב״כ״ף מרחשון הוא יום סגולה — יום הולדת כ״ק אדמו״ר מהורש״ב נ״ע״, ומעירה: <span class=\"qt cite\" data-ex=\"RB747-2\" data-n=\"VY02:RB-747S\">״הקביעות דכ״ף מרחשון היא לעולם באותו יום בשבוע שבו חל ראש השנה״<\/span> (501). ובפרשת השבוע <span class=\"qt cite\" data-ex=\"RB747-3\" data-n=\"VY02:RB-747S\">״מצינו הדגשה מיוחדת... הן בנוגע לענין החינוך (ובפרטיות יותר — חינוך עצמו וחינוך הזולת)״<\/span>. חינוך עצמו — <span class=\"qt\">״עשה לך רב״<\/span>. ו״חינוך הזולת — כמפורש בפרשתנו אודות מעלתו של אברהם אבינו, היהודי הראשון, <span class=\"qt cite\" data-ex=\"RB736-1\" data-n=\"VY02:RB-736\">״כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך ה׳ לעשות צדקה ומשפט״<\/span>, חינוך הבנים והבנות (כולל <span class=\"qt\">״בניך אלו התלמידים״<\/span>) ב״דרך ה׳<span class=\"qt\">״, לימוד התורה — ״משפט״<\/span>, וקיום המצוות — <span class=\"qt\">״צדקה״<\/span>, כללות כל המצוות״ (501).<\/p>\n<aside class=\"synth\"><p id=\"x60d8d3\"><strong><span class=\"smark\">[סינתזה]<\/span><\/strong> כאן <span class=\"qt\">״משפט״<\/span> הוא לימוד התורה ו״צדקה״ — קיום המצוות; בהערות השוליים (73–74) מובאות הפניות לתורה אור ולליקוטי תורה (מי כתב את ההערות — לא צוין במה שקראנו; את המקורות לא פתחנו). <span class=\"qt cite\" data-ex=\"RB747-5\" data-n=\"VY02:RB-747S\">״צדקה — כללות כל המצוות״<\/span> הוא קרוב לתורה אור (<a class=\"xref\" href=\"#/biur/VY02/ch-%D7%90\" title=\"א. השורש: צדקה ומשפט הם ״דרך כלל״ כל המצוות, והמשפט הוא גבול לתענוגות\">פרק א<\/a>).<\/p><\/aside>\n<hr/>\n<\/section><section class=\"part\" data-part=\"ch-י\" id=\"ch-י\"><div class=\"part-head\"><h2 id=\"h-ch-י\">י. מה עולה מן השרשרת<\/h2><\/div>\n<p id=\"x63e782\"><em><span class=\"smark\">[סינתזה — כל הפרק]<\/span> חמישה חוטים שעוברים מדור לדור. הם מסוכמים כאן בקצרה; הניתוח המלא — מה נוסף בכל תחנה — בשלב 4.<\/em><\/p>\n<ol>\n<li id=\"xa8c529\">\n<p id=\"xa8c529-2\"><strong>צדקה ומשפט — כלל המצוות, ושני כיוונים.<\/strong> בתורה אור צדקה ומשפט הן <span class=\"qt cite\" data-ex=\"AZ-3\" data-n=\"VY02:AZ-TO\">״דרך כלל כל מצות התורה״<\/span>. אצל מהר״ש הן <span class=\"qt\">״מקור לכל התרי״ג״<\/span> — צדקה למצוות עשה, ומשפט ללא תעשה. בתורת חיים נשאלת שאלת הכפל — שמירה ועשייה; בתרס״ז היא מקבלת תשובה בשני כיוונים — <span class=\"qt\">״דרך ה׳״<\/span> מלמעלה, <span class=\"qt\">״צדקה ומשפט״<\/span> מלמטה; ובתשל״ז הרבי מסביר שבמאמר הראשון צדקה ומשפט הן פירוש של דרך ה׳, ובשני — <span class=\"qt\">״ענין נוסף״<\/span>.<\/p>\n<\/li>\n<li id=\"x373bcf\">\n<p id=\"x373bcf-2\"><strong>משפט — גבול שהאדם שם למותרותיו.<\/strong> בתורה אור: <span class=\"qt cite\" data-ex=\"AZ-4\" data-n=\"VY02:AZ-TO\">״משפט שעושה האדם בנפשו על מותרות חיי גופו נגד הצדקה״<\/span>. אצל אדמו״ר האמצעי — <span class=\"qt\">״בכדי שלא יתעורר... לבחי׳ המותרות״<\/span>. ובתשל״ז — <span class=\"qt cite\" data-ex=\"RB737-10\" data-n=\"VY02:RB-737\">״שישפוט את עצמו מהמותרות״<\/span>, עם הפניה מפורשת לתורה אור.<\/p>\n<\/li>\n<\/ol>\n<p id=\"x726967\"><strong>פר״ת — סינון ההמשכה.<\/strong> שם המשפט נידון מצד מה שנמשך מלמעלה: <span class=\"qt cite\" data-ex=\"RS680-7\" data-n=\"VY02:RS-680\">״שיומשך למקום הראוי דוקא, ומה שאינו ראוי יהי׳ נדחה״<\/span>. זהו חוט קרוב, אך אינו זהה לחשבון שהאדם עושה במותרותיו.<\/p>\n<ol start=\"3\">\n<li id=\"x3e9eae\">\n<p id=\"x3e9eae-2\"><strong>ידיעה וחיבה.<\/strong> החיבה כבר באור התורה פט, א, לפי הציטוט שמביא המו״ל; אצל מהר״ש היא מובאת ומתפתחת במשל המשקה והעודר. בתרס״ו — בלשון <span class=\"qt\">״וי״ל״<\/span>, רצון ותענוג, וגם משל אהבת האב לבנו <span class=\"qt cite\" data-ex=\"RS666-10\" data-n=\"VY02:RS-666\">״גם כשהבן אינו כדבעי״<\/span>. בתרס״ז ובתשל״ז — חיבה, תענוג עצמי.<\/p>\n<\/li>\n<li id=\"x177980\">\n<p id=\"x177980-2\"><strong>הבחירה.<\/strong> באור התורה פט, א מובא העניין בשם הפנים יפות, לפי הערת המו״ל; בגוף מאמר מהר״ש — <span class=\"qt\">״ואפ״ל״<\/span>, שורה אחת. בתרס״ו — <span class=\"qt\">״הבחירה חפשית״<\/span>. בפר״ת — <span class=\"qt\">״(כן פי׳ הפנ״י)״<\/span>, עם נימוק לשוני. ובתשל״ו — כוח שניתן מלמעלה ועבודה שהיא של האדם — <span class=\"qt cite\" data-ex=\"RB736-10\" data-n=\"VY02:RB-736\">״ועד שאין זה נהמא דכיסופא כי זוהי עבודתו (שלו)״<\/span>.<\/p>\n<\/li>\n<li id=\"x710b28\">\n<p id=\"x710b28-2\"><strong><span class=\"qt cite\" data-ex=\"MZSH-3\" data-n=\"VY02:MZ-SH\">״אשר יצוה את בניו״<\/span>.<\/strong> בתורת חיים: <span class=\"qt cite\" data-ex=\"MZTC-2\" data-n=\"VY02:MZ-TC\">״שיצוה להם שיהי׳ בהם הכח ועוז״<\/span>. בתרפ״ד: <span class=\"qt\">״המצוה, כלומר המחבר״<\/span>. בתש״ז: <span class=\"qt\">״צוותא והתקשרות״<\/span>; בתשל״ו: <span class=\"qt\">״צוותא וחיבור״<\/span>. בתשל״ז: <span class=\"qt\">״נתינת כח מיוחד... לכל אחד מישראל״<\/span>, <span class=\"qt cite\" data-ex=\"RB736-7\" data-n=\"VY02:RB-736\">״עד סוף כל הדורות״<\/span>. ובשיחת תשמ״ז: <span class=\"qt cite\" data-ex=\"RB747-5\" data-n=\"VY02:RB-747S\">״חינוך הבנים והבנות (כולל ״בניך אלו התלמידים״<\/span>)<span class=\"qt cite\" data-ex=\"RY692-3\" data-n=\"VY02:RY-692\">״. לצד זה, בגשרים — אב שאומר לבנו מאמר ביום בר המצוה שלו, ובן שאומר ״כמעט בכל שנה ושנה הייתי שומע דא״ח מאדמו״ר נ״ע ביום זה״<\/span>.<\/p>\n<\/li>\n<\/ol>\n<p id=\"x261c00\"><strong>הפרשה והיום.<\/strong> את הקשר בין הפסוק לכ׳ מרחשון אומרים במפורש רק הרבי — בתשל״ו (<span class=\"qt cite\" data-ex=\"RB736-1\" data-n=\"VY02:RB-736\">״ומביא ע״ז בעל יום ההולדת״<\/span>), בתשל״ז (<span class=\"qt cite\" data-ex=\"RB737-1\" data-n=\"VY02:RB-737\">״ומדייק בזה בעל יום ההולדת״<\/span>, והערה 42) ובשיחת תשמ״ז — ולצידו המו״לים והכותרות. בטקסטים שקראנו לשרשרת לא מצאנו אזכור של ישיבת תומכי תמימים (את הצמח צדק ואת תרפ״ו לא קראנו).<\/p>\n<hr/>\n<\/section><section class=\"part\" data-part=\"sources\" id=\"sources\"><div class=\"part-head\"><h2 id=\"h-sources\">מקורות<\/h2><\/div>\n<p id=\"xd891fa\"><strong>הטקסטים שנקראו במלואם (או בקטע על הפסוק)<\/strong><\/p>\n<ul>\n<li class=\"srcitem\" data-n=\"VY02:MH-627\" id=\"xa73f27\" tabindex=\"0\">אדמו״ר מהר״ש, ד״ה כי ידעתיו, (ש״פ וירא) תרכ״ז — <a class=\"nref\" data-n=\"VY02:MH-627\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26\" rel=\"noopener noreferrer\" target=\"_blank\">תורת שמואל ספר תרכ״ז ע׳ טז–כב, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a>; גוף המאמר גם ב<a href=\"https://www.chabadlibrary.org/books/2000560007\" rel=\"noopener noreferrer\" target=\"_blank\">ספריית חב״ד<\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:MH-634\" id=\"xa82e36\" tabindex=\"0\">אדמו״ר מהר״ש, ד״ה כי ידעתיו, ש״פ וירא תרל״ד — <a class=\"nref\" data-n=\"VY02:MH-634\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=59\" rel=\"noopener noreferrer\" target=\"_blank\">תורת שמואל ספר תרל״ד ע׳ מז–נג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RS-666\" id=\"x8a07d0\" tabindex=\"0\">אדמו״ר הרש״ב, ד״ה כי ידעתיו, ש״פ וירא תרס״ו — <a class=\"nref\" data-n=\"VY02:RS-666\" href=\"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=99\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תרס״ו (מהדורה חדשה) ע׳ צא–קג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RS-667\" id=\"xaceef6\" tabindex=\"0\">אדמו״ר הרש״ב, ד״ה והוי׳ אמר המכסה, ש״פ וירא תרס״ז — <a class=\"nref\" data-n=\"VY02:RS-667\" href=\"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533\" rel=\"noopener noreferrer\" target=\"_blank\">שם, ע׳ תקכה–תקלז, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RS-670\" id=\"xde9fda\" tabindex=\"0\">אדמו״ר הרש״ב, מאמר בלי התחלה (<span class=\"qt\">״וע״פ הנ״ל יובן״<\/span>), עת״ר — <a class=\"nref\" data-n=\"VY02:RS-670\" href=\"https://media.col.org.il/files/uploads/original/2019/05/5cdd3ae925c47_1558002409.pdf#page=91\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ עת״ר (מהדורה חדשה) ע׳ עט–פו, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RS-680\" id=\"xdb412e\" tabindex=\"0\">אדמו״ר הרש״ב, ד״ה כי ידעתיו, ש״פ וירא פר״ת — <a class=\"nref\" data-n=\"VY02:RS-680\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=142\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תר״פ ע׳ קלב–קמ, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RY-684\" id=\"x7001d7\" tabindex=\"0\">אדמו״ר הריי״צ, ד״ה כי ידעתיו, ש״פ וירא תרפ״ד — <a class=\"nref\" data-n=\"VY02:RY-684\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=88\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תרפ״ד ע׳ פ–צג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RY-707\" id=\"x9671bf\" tabindex=\"0\">אדמו״ר הריי״צ, ד״ה כי ידעתיו, ש״פ וירא תש״ז — <a class=\"nref\" data-n=\"VY02:RY-707\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca0884b982bb_1554024523.pdf#page=66\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תש״ז ע׳ 188–195, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RB-736\" id=\"xe57b07\" tabindex=\"0\">הרבי, ד״ה כי ידעתיו, ש״פ וירא, כ׳ מרחשון תשל״ו — סה״מ בראשית ח״א ע׳ ריד ואילך; קראנו ב־<a class=\"nref\" data-n=\"VY02:RB-736\" href=\"https://maamarim.com/maamar.html?id=gb_946\" rel=\"noopener noreferrer\" target=\"_blank\"><span class=\"ltr\" dir=\"ltr\">maamarim.com<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RB-737\" id=\"x536fe8\" tabindex=\"0\">הרבי, ד״ה וה׳ אמר המכסה, ש״פ וירא, כ״ף מרחשון תשל״ז — <a class=\"nref\" data-n=\"VY02:RB-737\" href=\"https://www.chabadlibrary.org/books/1500360308\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ מלוקט ח״א ע׳ רנה–רסא, ספריית חב״ד<\/a><\/li>\n<\/ul>\n<p id=\"x45a0c7\"><strong>מקורות השורש<\/strong><\/p>\n<ul>\n<li class=\"srcitem\" data-n=\"VY02:AZ-TO\" id=\"x5d4737\" tabindex=\"0\">אדמו״ר הזקן, ד״ה אז ישיר — <a class=\"nref\" data-n=\"VY02:AZ-TO\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=133\" rel=\"noopener noreferrer\" target=\"_blank\">תורה אור בשלח סב, ד – סג, ג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:AZ-HOS\" id=\"x8632c1\" tabindex=\"0\">אדמו״ר הזקן, <span class=\"qt\">״המכסה אני מאברהם״<\/span> — <a class=\"nref\" data-n=\"VY02:AZ-HOS\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5c9c9109c32f5_1553764617.pdf#page=520\" rel=\"noopener noreferrer\" target=\"_blank\">מאמרי אדה״ז בראשית־שמות, הוספות/וירא ע׳ 6, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:MZ-SH\" id=\"x3f3f81\" tabindex=\"0\">אדמו״ר האמצעי, ד״ה אשירה — <a class=\"nref\" data-n=\"VY02:MZ-SH\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5c9cb0eb96006_1553772779.pdf#page=116\" rel=\"noopener noreferrer\" target=\"_blank\">מאמרי אדה״א שמות ח״א ע׳ קח, קטז–קיז, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:MZ-TC\" id=\"xa106dd\" tabindex=\"0\">אדמו״ר האמצעי, ביאור לד״ה אשירה — <a class=\"nref\" data-n=\"VY02:MZ-TC\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=340\" rel=\"noopener noreferrer\" target=\"_blank\">תורת חיים שמות ח״א קסט, ג – קעה, ג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:MZ-577\" id=\"xb037a8\" tabindex=\"0\">אדמו״ר האמצעי, ד״ה עזי וזמרת, אחרון של פסח תקע״ז (הנחה) — <a class=\"nref\" data-n=\"VY02:MZ-577\" href=\"https://www.chabadlibrary.org/books/1900740011\" rel=\"noopener noreferrer\" target=\"_blank\">מאמרי אדה״א הנחות תקע״ז ע׳ נח, ספריית חב״ד<\/a><\/li>\n<\/ul>\n<p id=\"x7be678\"><strong>הגשרים לכ׳ מרחשון<\/strong><\/p>\n<ul>\n<li class=\"srcitem\" data-n=\"VY02:MH-634\" id=\"xd2eb15\" tabindex=\"0\">אדמו״ר מהר״ש, <span class=\"qt\">״איתא במדרש תילים״<\/span>, בר המצוה של הרש״ב, כ׳ מרחשון תרל״ד — <a class=\"nref\" data-n=\"VY02:MH-634\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=65\" rel=\"noopener noreferrer\" target=\"_blank\">תורת שמואל תרל״ד ע׳ נג, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RY-692\" id=\"xc01c19\" tabindex=\"0\">אדמו״ר הריי״צ, ד״ה כי נר מצוה, ש״פ וירא, כ׳ מ״ח תרצ״ב — <a class=\"nref\" data-n=\"VY02:RY-692\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca091ed246d3_1554026989.pdf#page=129\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תרצ״ב ע׳ קכ, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a>; גם ב<a href=\"https://www.chabadlibrary.org/books/2700520064\" rel=\"noopener noreferrer\" target=\"_blank\">ספריית חב״ד<\/a><\/li>\n<li class=\"srcitem\" data-n=\"VY02:RB-747S\" id=\"x85e1fa\" tabindex=\"0\">הרבי, משיחות ש״פ וירא, כ״ף מרחשון תשמ״ז — <a class=\"nref\" data-n=\"VY02:RB-747S\" href=\"https://media.col.org.il/files/uploads/original/2019/05/5cee68bdcc3a6_1559128253.pdf#page=511\" rel=\"noopener noreferrer\" target=\"_blank\">תורת מנחם תשמ״ז ח״א ע׳ 494, 501, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<\/ul>\n<p id=\"x1f50b9\"><strong>מקבילות שנקראו רק במקום הפסוק<\/strong><\/p>\n<ul>\n<li class=\"srcitem\" data-n=\"VY02:RY-688\" id=\"x955aab\" tabindex=\"0\">אדמו״ר הריי״צ, ד״ה זה היום — <a class=\"nref\" data-n=\"VY02:RY-688\" href=\"https://media.col.org.il/files/uploads/original/2019/05/5ce4e85725e1b_1558505559.pdf#page=374\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תרפ״ח ע׳ קנג, קנו, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a>; <a class=\"nref\" data-n=\"VY02:RY-708\" href=\"https://media.col.org.il/files/uploads/original/2019/03/5ca08da2cf1bd_1554025890.pdf#page=244\" rel=\"noopener noreferrer\" target=\"_blank\">סה״מ תש״ח ע׳ 239, 241, <span class=\"ltr\" dir=\"ltr\">COL<\/span><\/a><\/li>\n<\/ul>\n<p id=\"x37c2fc\"><strong>ידועים מהפניה בלבד (לא נקראו)<\/strong><\/p>\n<ul>\n<li id=\"x839880\">הצמח צדק, <span class=\"qt\">״כי ידעתיו״<\/span> — אור התורה וירא, פט, א–ב; צו, א (לפי המו״לים בתורת שמואל ובהמשך תרס״ו); אור התורה וירא כרך ד, תשלה (לפי המו״ל בתרס״ז, הערה 126)<\/li>\n<li class=\"srcitem\" data-n=\"VY02:RY-686\" id=\"x805493\" tabindex=\"0\">אדמו״ר הריי״צ, ד״ה כי ידעתיו, <span class=\"qt\">״וירא, כ׳ מ״ח״<\/span> תרפ״ו — סה״מ תרפ״ו ע׳ קא (מפתח הכרך, <a class=\"nref\" data-n=\"VY02:RY-686\" href=\"https://hebrewbooks.org/pdfpager.aspx?req=31675&amp;pgnum=4\" rel=\"noopener noreferrer\" target=\"_blank\">היברובוקס<\/a>)<\/li>\n<li id=\"x26b72a\">אדמו״ר האמצעי, ד״ה ובבואה לפני המלך — מאמרי אדה״א נ״ך ע׳ תפג (לפי המו״ל בתרס״ו)<\/li>\n<\/ul>\n<hr/>\n<\/section><section class=\"part\" data-part=\"open\" id=\"open\"><div class=\"part-head\"><h2 id=\"h-open\">פתוח לבקרה<\/h2><\/div>\n<ul>\n<li id=\"x3c852a\"><strong>הצמח צדק ותרפ״ו לא נקראו.<\/strong> לפי המו״ל, מאמר מהר״ש הוא הנחה של מאמר הצמח צדק. מן ההערות כבר ידוע שאור התורה פט, א–ב הוא מקור להתחלת המאמר ולסיומו — ובהם חיבה ובחירה — ואור התורה צו, א הוא קיצור תוכן מאמר מהר״ש; היחס המדויק בין שני המקומות לבין נוסח מהר״ש לא הוכרע בלי פתיחתם. תרפ״ו הוא המאמר היחיד של הריי״צ על הפסוק שנאמר בכ׳ מרחשון (לפי המפתח), והרבי מפנה אליו בתשל״ז (הערות 11, 33). צריך לפתוח את שניהם (היברובוקס 31650, 31675).<\/li>\n<li id=\"x55f2de\"><strong>מעמד הגהה של תשל״ז — הוכרע בבקרה:<\/strong> מוגה. פתח הדבר של <span class=\"qt\">״ספר המאמרים מלוקט״<\/span> אומר שהוא <span class=\"qt cite\" data-ex=\"RB737-31\" data-n=\"VY02:RB-737/פתח דבר\">״הכולל את כל מאמרי החסידות של כ״ק אדמו״ר... אשר הוגהו על ידו״<\/span>, ושגוף המאמרים שרק התחלתם וסיומם הוגהו נדפס ב־״הוספות״ כ־״הנחה בלתי מוגה״; המאמר שלנו נדפס בגוף הספר (ע׳ רנה). הכרטיס ב־<span class=\"ltr\" dir=\"ltr\">meta.json<\/span> כבר תוקן ל״מוגה״; גם כותרת הנתונים של הטקסט השמור הותאמה אליו.<\/li>\n<li id=\"x5b1eb3\"><strong>תשל״ו:<\/strong> קראנו מ־<span class=\"ltr\" dir=\"ltr\">maamarim.com<\/span>, לא מצילום הספר; ייתכנו הבדלי נוסח קלים.<\/li>\n<li id=\"x86214b\"><strong>משל אהבת האב לבן בתרס״ו<\/strong> — הסמיכות ל״יצוה את בניו״ היא שלנו (מסומנת), והמאמר אינו עושה אותה.<\/li>\n<li id=\"xa4aab4\"><strong>פירוש הערה 42 בתשל״ז<\/strong> — ההתאמה בין הקביעות לתוכן המאמרים היא בלשון <span class=\"qt\">״להעיר״<\/span> ו״ואולי יש לומר״; שמרנו את הסייגים.<\/li>\n<li id=\"x2a5f2f\"><strong><span class=\"qt\">״לא מצאנו״<\/span><\/strong> — בטקסטים שנקראו לשרשרת הזאת בלבד.<\/li>\n<\/ul><\/section>","ex":{"AZ-1":["סג, א",133,"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=133","VY02:AZ-TO","צדקה ומשפט — דרך כלל המצוות","״וכמו שהוא לענין תורה כך הוא לענין שאר מצות דכתיב ושמרו דרך ה׳ לעשות צדקה ומשפט למען הביא ה׳ על אברהם את אשר דבר עליו שע״י המצות שנקראו דרך כלל בשם צדקה ומשפט כמו שיתבאר נמשך על בחי׳ אברהם שהיא מדת האהבה ברצוא הלוך ונסוע״","צילום הדף (COL)","",""],"AZ-2":["סג, ב",133,"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=133","VY02:AZ-TO","דרך הוי׳ — דרך ומבוא","״פירוש דרך ומבוא להיות הוי׳״","צילום הדף (COL)","",""],"AZ-3":["סג, ב",133,"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=133","VY02:AZ-TO","התעוררות מלמטה בצדקה ומשפט","״והיא על ידי אתערותא דלתתא בצדקה ומשפט שהן דרך כלל כל מצות התורה״\n\n״דרך כלל כל מצות התורה״","צילום הדף (COL)","",""],"AZ-4":["סג, ב",133,"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=133","VY02:AZ-TO","משפט על המותרות","״ובחי׳ משפט זה אשר לאלהים הוא על ידי אתערותא דלתתא בחי׳ משפט שעושה האדם בנפשו על מותרות חיי גופו נגד הצדקה״\n\n״חייך קודמין לחיי חבירך ודוקא חייך ממש כמשל הקיתון של מים... מה שאין כן המותרות שלך אינן קודמין לחיי חבירך שאינו בדין שיפנק האדם את נפשו בתפנוקי עלמא וחבירו ימות ברעב ח״ו״\n\n״משפט שעושה האדם בנפשו על מותרות חיי גופו נגד הצדקה״","צילום הדף (COL)","",""],"AZ-5":["סג, ג (עמ׳ 126)",134,"https://media.col.org.il/files/uploads/original/2019/03/5c9cab77468d2_1553771383.pdf#page=134","VY02:AZ-TO","כל המצוות נקראות צדקה","״והנה גם שאר מצות התורה נקראות בשם צדקה על דרך זה כי רמ״ח מצות עשה הם רמ״ח אברין דמלכא״","צילום הדף (COL)","",""],"MZSH-1":["קח (הערת המו״ל)",108,"https://media.col.org.il/files/uploads/original/2019/03/5c9cb0eb96006_1553772779.pdf#page=108","VY02:MZ-SH","המו״ל: מיוסד על תו״א","״מיוסד על ד״ה זה בתורה אור״\n\n״המאמר מיוסד על ד״ה זה בתורה אור בשלח סב, ד״","צילום הדף (COL)","",""],"MZSH-2":["קטז",116,"https://media.col.org.il/files/uploads/original/2019/03/5c9cb0eb96006_1553772779.pdf#page=116","VY02:MZ-SH","משפט בצדקה — לא למותרות","״ובכל זה יובן מה שהזכיר מדת משפט בצדקה... הכל מטעם הנ״ל בכדי שלא יתעורר אתעדל״ע לבחי׳ המותרות אלא רק להחיות רוח שפלים במקום מותרות כו׳״","צילום הדף (COL)","",""],"MZSH-3":["קטז",116,"https://media.col.org.il/files/uploads/original/2019/03/5c9cb0eb96006_1553772779.pdf#page=116","VY02:MZ-SH","אברהם — רצוא ושוב","״כי ידעתיו למען אשר יצוה את בניו״\n\n״וזהו המשך דברי הפסוק כי ידעתיו... פי׳ למען הביא על אברהם כו׳ כי בחי׳ אברהם הי׳ בבחי׳ רצוא ושוב״\n\n״אשר יצוה את בניו״","צילום הדף (COL)","",""],"MZSH-4":["קיז",117,"https://media.col.org.il/files/uploads/original/2019/03/5c9cb0eb96006_1553772779.pdf#page=117","VY02:MZ-SH","עליו — למעלה הימנו","״פי׳ עליו למעלה הימנו דוקא, והוא בחי׳ אדון הנפלאות הנ״ל שע״י דביקות הנפש לא תגיע לזה רק דוקא ע״י עסק התורה ומצות שנק׳ צדק[ה] ומשפט״","צילום הדף (COL)","",""],"MZTC-1":["קסט, ג (עמ׳ 338)",340,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=340","VY02:MZ-TC","שאלת הכפל — שמירה ועשייה","״וא״כ יש להבין מ״ש עוד לעשות צדקה ומשפט... ומה זה שכפל הדברים לומר ב׳ דברים שמירה בדרך הוי׳ ועשי׳ בצדקה כו׳״\n\n״שמירה בדרך הוי׳ ועשי׳ בצדקה״","צילום הדף (COL)","",""],"MZTC-2":["קסט, ד (עמ׳ 338)",340,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=340","VY02:MZ-TC","שמירה בכוונה","״וז״ש אשר יצוה את בניו ושמרו דרך הוי׳ שיצוה להם שיהי׳ בהם הכח ועוז לשמור דרך הוי׳, וכל שמירה הוא במח׳ וכוונה ורעותא דלבא״\n\n״שיהי׳ בהם הכח ועוז״\n\n״שיצוה להם שיהי׳ בהם הכח ועוז״","צילום הדף (COL)","",""],"MZTC-3":["קעה, ג (עמ׳ 350)",352,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=352","VY02:MZ-TC","להעלותו למעלה משרשו","״להעלותו למעלה משרשו הראשון״","צילום הדף (COL)","",""],"MZTC-4":["339 (הערה 309)",341,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=341","VY02:MZ-TC","המו״ל: מקבילות","״הנחות תקע״ז כאן (ע׳ נט)״","צילום הדף (COL)","",""],"M577-1":["נח",null,"https://www.chabadlibrary.org/books/1900740011","VY02:MZ-577","כותרת","״אחרון של פסח, תקע״ז״","טקסט דיגיטלי בספריית חב״ד","",""],"M577-2":["נח",null,"https://www.chabadlibrary.org/books/1900740011","VY02:MZ-577","סמיכות צדקה למשפט","״וצ״ל ענין הסמיכות צדקה למשפט כי צדקה ומשפט המה שני הפכים בתכלית, כי הצדקה היא לפנים משורת הדין ומשפט הוא להיות מכלכל דבריו במשפט דייקא כו׳״","טקסט דיגיטלי בספריית חב״ד","",""],"M577-3":["נט",null,"https://www.chabadlibrary.org/books/1900740011","VY02:MZ-577","רחמי המלך","״כמו למשל מלך המתנשא בתכלית הרוממות אזי יפול אצלו רחמנות על השפל ביותר... משא״כ שר אשר אינו בהתנשאות כמו המלך לא ירחם כ״כ על השפל ביותר כו׳״","טקסט דיגיטלי בספריית חב״ד","",""],"MH627-1":["טז",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","כותרת","״בס״ד. (ש״פ וירא) ך״ז.״","צילום הדף (COL)","",""],"MH627-2":["טז",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","פתיחה: תרגום ורש״י","״שאונקלוס תרגם לשון כי ידעתיו ארי גלי קדמי, ורש״י פי׳ כי ידעתיו לשון חיבה, דלפי פי׳ הת״א אין למען נופל על הלשון״\n\n״קיים אברהם כל התורה כולה עד שלא ניתנה״\n\n״כמו מצות תפילין שהם ד׳ פרשיות קדש והי׳ כי יביאך שמבואר סיפור יצ״מ ועדיין לא הי׳ שעבוד מצרים״","צילום הדף (COL)","",""],"MH627-3":["טז (הערת המו״ל)",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","המו״ל: מקור המאמר","״הוא ד״ה זה להצ״צ בגוכי״ק כ״ק אדמו״ר מהר״ש בכת״י 1077... [הכולל הנחות אדמו״ר מהר״ש ממאמרי הצ״צ]. וכאן הוא בתוס׳ הגהות. תוכן המאמר נמצא בקיצור (כפי שנרשם ע״י הצ״צ) בד״ה זה באוה״ת וירא צו, א״","צילום הדף (COL)","",""],"MH627-4":["טז (הערת המו״ל)",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","המו״ל: מפת הנוסחים","״המאמר נמצא בשינויים קלים בד״ה זה בסה״מ תרל״ד... ובתוס׳ ביאור והוספות בד״ה זה בסה״מ פר״ת... ובד״ה זה בסה״מ תרפ״ו... ובד״ה זה היום עשה הוי׳ בסה״מ תרפ״ח... ובסה״מ תש״ח״","צילום הדף (COL)","",""],"MH627-6":["טז",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","ר׳ שמלאי — דוד","״שדוד אמר שכ״א יקיים הי״א מדות אלו וממילא יבא על ידם לקיום כל התרי״ג מצות״","צילום הדף (COL)","",""],"MH627-7":["יז",27,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=27","VY02:MH-627","ישעיה — צדקה ומשפט","״ובא ישעי׳ והעמידן על שנים שהם צדקה ומשפט, לפי שב׳ מצות אלו הם מקור לכל התרי״ג מצות, וכמשי״ת, וז״ש באברהם ושמרו דרך ה׳ לעשות צדקה ומשפט״","צילום הדף (COL)","",""],"MH627-8":["יח",28,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=28","VY02:MH-627","למה עניים ועשירים","״ולכאו׳ צ״ל למה הי׳ לו ית׳ לבראות עניים ועשירים... דהי׳ לו לעשות שכאו״א יהי׳ לו כדי פרנסתו ולא יצטרכו עמך ישראל זה לזה״","צילום הדף (COL)","",""],"MH627-9":["יח (הערת המו״ל)",28,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=28","VY02:MH-627","המו״ל: תו״א בשלח","״בהבא לקמן (בענין לעשות צדקה ומשפט) ראה תו״א בשלח סג, סע״א ואילך״","צילום הדף (COL)","",""],"MH627-10":["יט",29,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=29","VY02:MH-627","צדקה — שורש רמ״ח","״ע״י מה שנותן העשיר צדקה למטה עי״ז נמשך בחי׳ הצדקה למעלה כו׳, והיינו ע״י בחי׳ הביטול שמה שמשתכר ביגיע כפו נותן לחבירו״","צילום הדף (COL)","",""],"MH627-11":["יט",29,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=29","VY02:MH-627","משפט — כל אחד במקומו","״וארז״ל בירושלמי וכי יש משפט לעצים אלא קרש שזכה בדרום ינתן בדרום, והיינו שכ״א על מקומו יבא בשלום״","צילום הדף (COL)","",""],"MH627-12":["כ",30,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=30","VY02:MH-627","משפט — שורש שס״ה","״המשפט הוא שרש לשס״ה ל״ת״\n\n״וענין המשפט הוא לבער הרע ולברור אותו מן הטוב כו׳״","צילום הדף (COL)","",""],"MH627-13":["כ",30,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=30","VY02:MH-627","מה נתחדש במתן תורה","״אברהם שקיים התורה עי״ז המשיך גילוי אלקות למעלה... אך להיות נמשך המשכת אלקותו ית׳ ע״י המצות גשמי׳ זהו ענין התחדשות מ״ת״","צילום הדף (COL)","",""],"MH627-14":["כא",31,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=31","VY02:MH-627","עליו — רב חסד; האבות הכנה","״כי על בחי׳ החסד דאברהם הביא עליו בחי׳ חסד דמשה דאקרי רב חסד״\n\n״האבות עשו הכנה למ״ת״","צילום הדף (COL)","",""],"MH627-15":["כא",31,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=31","VY02:MH-627","דרך הוי׳ — אותיות השם","״וזהו ושמרו דרך הוי׳ שעשו בחי׳ שם הוי׳ יו״ד צמצום ה׳ התפשטות וא״ו המשכה כו׳, וע״י הכנה זו שעשו המשיך משה אח״כ למטה״","צילום הדף (COL)","",""],"MH627-16":["כא",31,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=31","VY02:MH-627","ידעתיו — חיבה","״כי ל׳ ידעתיו ל׳ ידיעה אינו שייך לומר שעכשיו ידע ומקודם לא ידע, רק שפי׳ ידעתיו הוא לשון חיבה כמו רק אתכם ידעתי מכל העמים״","צילום הדף (COL)","",""],"MH627-17":["כא–כב",31,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=31","VY02:MH-627","משקה ועודר","״משל לאחד כשהוא משקה משקה לכל השדה, כשהוא עודר אינו עודר אלא הטובים״\n\n״ויתרון על המלאכה כלליות״","צילום הדף (COL)","",""],"MH627-18":["כב",32,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=32","VY02:MH-627","סיום: חיבה ובחירה","״וכך יובן זה למעלה... כשהוא עודר דהיינו בחי׳ השפעה פנימיות בחי׳ תומ״צ אינו עודר אלא הטובים... וזהו כי ידעתיו שהוא ל׳ חיבה למען אשר יצוה״\n\n״ולפי׳ התרגום שפי׳ ארי גלי קדמי, צ״ל לשון למען כנ״ל, ואפ״ל אף כי גליא קדמי אעפ״כ הידיעה אינה מכרחת הבחירה כו׳״","צילום הדף (COL)","",""],"MH627-19":["כב (הערת המו״ל)",32,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=32","VY02:MH-627","המו״ל: הפנים יפות","״בשם הפנים יפות להרה״ק ר׳ פינחס בעל ההפלאה״\n\n״דתיבת למען הוא שלא נאמר שהידיעה גורמת הבחירה... ונהפוך הוא אשר הבחירה דהיינו הציווי אשר יצוה היא גורמת הידיעה״","צילום הדף (COL)","",""],"MH627-22":["יז (הערת המו״ל)",27,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=27","VY02:MH-627","המו״ל: תוספת בתרפ״ח ותש״ח","״בסה״מ תרפ״ח ותש״ח שם מוסיף כאן״","צילום הדף (COL)","",""],"MH627-23":["טז (הערת המו״ל)",26,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=26","VY02:MH-627","המו״ל: הגהה בפר״ת","״(וצ״ע בכוונת רש״י שם)״\n\n״בד״ה זה פר״ת נוספה כאן הגהה: ״וצ״ע בכוונת רש״י שם״","צילום הדף (COL)","",""],"MH634-2":["מז (הערה 1)",59,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=59","VY02:MH-634","המו״ל: יחס לתרכ״ז","״ד״ה זה דשנת תרכ״ז... בכמה שינויים קלים״\n\n״הוא ד״ה זה דשנת תרכ״ז [סה״מ תרכ״ז ע׳ כב ואילך, בכמה שינויים קלים אשר יצויינו להלן בשוה״ג]״","צילום הדף (COL)","",""],"MH634-3":["מז (הערה 4)",59,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=59","VY02:MH-634","שינוי נוסח","״לא יוצלח לשון למען הנכתב אחריו: בסה״מ תרכ״ז שם: אין למען נופל על הלשון״","צילום הדף (COL)","",""],"M634B-1":["נג",65,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=65","VY02:MH-634B","פתיחה: תפילין","״איתא במדרש תילים ר׳ אליעזר אומר אמרו ישראל לפני הקב״ה רבש״ע רוצין אנו ליגע בתורה יומם ולילה אבל אין לנו פנאי א״ל הקב״ה קיימו מצות תפילין ומעלה אני עליכם כאלו אתם יגיעים בתורה יומם ולילה״","צילום הדף (COL)","",""],"M634B-2":["נג",65,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=65","VY02:MH-634B","מצוה לאחרים ועושה","״יש מי שהוא מצוה לאחרים לעשות והוא אינו עושה אבל הקב״ה מה שהוא עושה אומר לישראל לעשות״","צילום הדף (COL)","",""],"M634B-3":["נג (הערה 1)",65,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=65","VY02:MH-634B","המו״ל: בר המצוה","״נאמר על בר מצוה של בנו אדמו״ר מהורש״ב נ״ע — ביום כ׳ מר־חשון תרל״ד״\n\n״בר מצוה של בנו אדמו״ר מהורש״ב נ״ע״\n\n״וע״ש אשר מאמר זה חזר אותו ג״כ כ״ק אדמו״ר מהוריי״צ נ״ע בחגיגת הבר מצוה שלו (ביום יב תמוז תרנ״ג)״","צילום הדף (COL)","",""],"M634B-5":["נג (הערה 6)",65,"https://media.col.org.il/files/uploads/original/2019/03/5ca061012a6cc_1554014465.pdf#page=65","VY02:MH-634B","המו״ל: הבן שאל את אביו","״שאלתי את כ״ק אאמו״ר וענני״","צילום הדף (COL)","",""],"RS666-1":["צא",99,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=99","VY02:RS-666","כותרת","״בס״ד, ש״פ וירא, רס״ו״","צילום הדף (COL)","",""],"RS666-2":["צא",99,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=99","VY02:RS-666","השאלה","״מהו ההפרש ביניהם ברוחניות״\n\n״וצ״ל דבאמת לפי התרגום תי׳ למען אין לו פי׳ כלל, ואיך מפרש כי ידעתיו לשון ידיעה. וגם צ״ל בפי׳ התרגום ופי׳ רש״י שמפרשים לשון ידיעה ולשון חיבה, מהו ההפרש ביניהם ברוחניות, ומהו ענין החיבה״","צילום הדף (COL)","",""],"RS666-3":["צא (הערה 1)",99,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=99","VY02:RS-666","המו״ל: יסוד, התחלה וסיום","״מיוסד על ד״ה ובבואה לפני המלך במאמרי אדמו״ר האמצעי״","צילום הדף (COL)","",""],"RS666-4":["צג (כותרת העמוד)",101,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=101","VY02:RS-666","כ׳ מרחשון","״ש״פ וירא, כ״ף מרחשון, ה׳תרס״ו״","צילום הדף (COL)","",""],"RS666-5":["צג",101,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=101","VY02:RS-666","הרצון העצמי אינו משתנה","״לא ישונה כלל גם אם נשקע ח״ו בריבוי תענוגים גשמיים״","צילום הדף (COL)","",""],"RS666-6":["צג",101,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=101","VY02:RS-666","מים רבים","״וכמ״ש מים רבים לא יוכלו לכבות את האהבה, דמים רבים הן ריבוי התענוגים הגשמי׳, לא יוכלו לכבות את האהבה דכנס״י להקב״ה כו׳״\n\n״מים רבים לא יוכלו לכבות את האהבה״","צילום הדף (COL)","",""],"RS666-7":["צה",103,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=103","VY02:RS-666","כוח הרצון","״שיש בכח הרצון לעלות בעילוי אחר עילוי כ״כ בעצם הנפש ממש, שאין כח זה בתענוג כלל״","צילום הדף (COL)","",""],"RS666-8":["צו",104,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=104","VY02:RS-666","העונג פנימי יותר","״אין זה מפני שהרצון הוא למעלה מהעונג בעצם הנפש... ואדרבה, העונג הוא בעצם הנפש בבחי׳ פנימיות יותר״","צילום הדף (COL)","",""],"RS666-9":["צז",105,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=105","VY02:RS-666","רצון גלוי, עונג נעלם","״דברצון, גם בחי׳ הרצון העצמי מתפשט ומתגלה כמו שהוא, ובתענוג, מה שמתפשט ומתגלה הוא בחי׳ הארת העונג, אבל העונג העצמי אינו מתפשט ומתגלה כו׳״","צילום הדף (COL)","",""],"RS666-10":["צח",106,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=106","VY02:RS-666","אהבת האב לבן","״וכן הוא באהבת האב אל הבן, שרוצה בעצם מהות הבן דוקא... דגם כשהבן אינו כדבעי ח״ו, שאינו הולך בדרך הישר ר״ל, ומ״מ, האב רוצה בו בעצם... דמצד התענוג בודאי אינו מתענג בו כלל, ואדרבא, הוא מצטער מהנהגתו הלא טובה כו׳, אבל מצד הרצון ה״ה רוצה בו כו׳״\n\n״גם כשהבן אינו כדבעי״","צילום הדף (COL)","",""],"RS666-11":["קא",109,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=109","VY02:RS-666","הרצון שבמצוות","״רצון העצמי דפנימיות ועצמות א״ס ב״ה, שאינו מורכב בשום דבר, והוא במעשה המצות בפו״מ דוקא, ואין טעם לרצון זה כלל״","צילום הדף (COL)","",""],"RS666-12":["קב",110,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=110","VY02:RS-666","עכשיו רצון, לעתיד תענוג","״ומה שבא בהתגלות עכשיו הוא בחי׳ הרצון בלבד, ולעתיד יתגלה בחי׳ התענוג העצמי שברצון דמעהמ״צ״","צילום הדף (COL)","",""],"RS666-13":["קב",110,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=110","VY02:RS-666","רש״י — תענוג עצמי","״וע״פ הנ״ל יובן מ״ש כי ידעתיו למען אשר יצוה, דפירש״י לשון חיבה, והיינו בחי׳ תענוג העצמי שנמשך ע״י המצות בפו״מ... למען אשר יצוה כו׳ לעשות צדקה ומשפט, והיינו קיום המצות בפו״מ בבחי׳ קבעומ״ש״","צילום הדף (COL)","",""],"RS666-14":["קב–קג",110,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=110","VY02:RS-666","תרגום — ידיעה ובחירה","״שהידיעה אינו מכרחת את הבחירה, דאעפ״י שגלי קדמי, מ״מ, הבחירה חפשית, והיינו שהידיעה היא כמו שיהי׳ אחר הבחירה כו׳״","צילום הדף (COL)","",""],"RS666-15":["קג",111,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=111","VY02:RS-666","תרגום — רצון עצמי","״וי״ל דמה שהתרגום מפרש ל׳ ידיעה, ורש״י פי׳ לשון חיבה, הוא ההפרש בין בחי׳ רצון העצמי ובחי׳ עונג העצמי״","צילום הדף (COL)","",""],"RS666-16":["קג",111,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=111","VY02:RS-666","סיום","״שהרי ג״ז נמשך ע״י עשיות המצות בפו״מ דעכשיו, אלא שהגילוי יהי׳ לעתיד״","צילום הדף (COL)","",""],"RS666-17":["קב–קג (הערה 125)",110,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=110","VY02:RS-666","המו״ל: הפנים יפות","״הטעם שמביא זה בהמאמר דתרס״ו, נת׳ בסד״ה כי ידעתיו תשל״ו״","צילום הדף (COL)","",""],"RS667-1":["תקכה",533,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533","VY02:RS-667","כותרת ושאלה","״וה׳ אמר המכסה אני מאברהם כו׳ ואברהם היו יהי׳ לגוי גדול כו׳ כי ידעתיו... וצ״ל, מה״ע המכסה אני. גם צ״ל מ״ש ושמרו דרך ה׳ לעשות צדקה ומשפט, הלא דרך ה׳ זהו תומ״צ, וא״כ, מה צ״ל צדקה ומשפט״","צילום הדף (COL)","",""],"RS667-2":["תקכה",533,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533","VY02:RS-667","שני בירורים","״ולהבין כ״ז צלה״ק משנת״ל שיש ב׳ מיני בירורים. הא׳, בירור דאו״י שמלמעלה למטה, והב׳, בירור דאו״ח מלמטה למעלה״","צילום הדף (COL)","",""],"RS667-3":["תקכה",533,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533","VY02:RS-667","משל התינוק והאב","״ויובן זה עד״מ כמו התינוק הקטן שא״י לילך מכח עצמו, כ״א ע״י הגדול, כאביו, שעומד מאחוריו ואוחזו ומוליכו או דוחפו מאחוריו, שמכח זה ילך, ועצם ההילוך הוא שהולך בעצמו״","צילום הדף (COL)","",""],"RS667-4":["תקכז",535,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=535","VY02:RS-667","האב נושא את בנו","״או שאם קטן הוא ביותר שא״י לעמוד על רגליו כלל, ויגב[י]הנו האב על כתפו וישאנו כאשר ישא האומן את היונק כו׳, שאז צריך האב להשפיל למקום הנמוך ל[ה]עלות את בנו על כתפו״","צילום הדף (COL)","",""],"RS667-6":["תקכח",536,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=536","VY02:RS-667","משל הרב והתלמיד","״לעולם ישנה אדם לתלמידו בדרך קצרה״","צילום הדף (COL)","",""],"RS667-7":["תקכה (הערה 1)",533,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533","VY02:RS-667","המו״ל: יסוד","״מיוסד על: ד״ה ויקהל בתו״ח שמות ח״ב״","צילום הדף (COL)","",""],"RS667-8":["תקכה (הערה 1*)",533,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=533","VY02:RS-667","המו״ל: מאמר א׳ ומאמר ב׳","״שם נת׳ גם ההפרש בין מאמר זה (שהוא מאמר הב׳ דפ׳ וירא בהמשך תרס״ו) לבין ד״ה כי ידעתיו תרס״ו״","צילום הדף (COL)","",""],"RS667-10":["תקלז",545,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=545","VY02:RS-667","הסיום: המכסה, חיבה, דרך ה׳","״וז״ש כי ידעתיו למען אשר יצוה, פי׳ כי ידעתיו ל׳ חיבה, שחיבב אותו בבחי׳ תענוג העצמי דעצמות א״ס ממש כו׳, והיינו בשביל אשר יצוה כו׳ ושמרו דרך ה׳ לעשות צדקה ומשפט, פי׳ דרך ה׳ היינו בבחי׳ המשכה מלמעלה למטה, וזהו אופן ההמשכה דתושב״כ. וענין צדקה ומשפט זהו העבודה בבחי׳ מלמטה למעלה״\n\n״בחי׳ העלם העצמי דא״ס, שנתגלה לאברהם... וזהו ע״י הנסיונות שלו״","צילום הדף (COL)","",""],"RS667-11":["תקלז",545,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=545","VY02:RS-667","יגיעה מלמטה","״וכ״ז הוא למען אשר יצוה כו׳, ושמרו דרך ה׳ לעשות צדקה ומשפט, שזהו העבודה ביגיעה מלמטה למעלה דוקא, שעי״ז דוקא נמשך גילוי בחי׳ העצמות כו׳״","צילום הדף (COL)","",""],"RS680-1":["קלב",142,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=142","VY02:RS-680","כותרת","״בס״ד ש״פ וירא, פר״ת.״","צילום הדף (COL)","",""],"RS680-2":["קלב–קלג",143,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=143","VY02:RS-680","השאלות","״למה נא׳ צדקה ומשפט הרי יש כמה ענינים בתורה כו׳. גם מ״ש למען הביא כו׳ את אשר דבר עליו צ״ל מהו אשר דבר עליו ולכאו׳ הול״ל אשר דבר לו מהו עליו כו׳״","צילום הדף (COL)","",""],"RS680-4":["קלו",146,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=146","VY02:RS-680","עשיר ועני, רב ותלמיד","״רש ואיש תככים נפגשו מאיר עיני שניהם ה׳, דכאשר העשיר מפרנס את העני אזי מאיר עיני שניהם ה׳, ושם גם בענין ההשפעה שכאשר הרב משפיע להתלמיד מאיר עיני שניהם ה׳ עיני הרב ועיני התלמיד כו׳״","צילום הדף (COL)","",""],"RS680-5":["קלו",146,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=146","VY02:RS-680","משפיע ומקבל","״וזהו שנבראו עניים ועשירים מפני שתכלית הכוונה בברה״ע הוא לא רק בשביל האור והגילוי שמאיר בעולמות כ״א להיות תוס׳ אור מבחי׳ עצמות א״ס וזה נמשך דוקא כאשר יש משפיע שהעשיר משפיע לעני כו׳״","צילום הדף (COL)","",""],"RS680-6":["קלז",147,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=147","VY02:RS-680","שני מיני רחמים","״מצד הרוממות שהוא ענין טבעי שטבע המרומם להיות נמשך אל השפל... וכמו רחמי המלך שמרובים מרחמי השר״","צילום הדף (COL)","",""],"RS680-7":["קלח",148,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=148","VY02:RS-680","משפט שבצדקה","״ע״ז הוא המשפט שיומשך למקום הראוי דוקא, ומה שאינו ראוי יהי׳ נדחה״\n\n״שיומשך למקום הראוי דוקא, ומה שאינו ראוי יהי׳ נדחה״","צילום הדף (COL)","",""],"RS680-8":["קלט",149,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=149","VY02:RS-680","עליו","״שלמעלה ממנו ושהוא כלי לזה״","צילום הדף (COL)","",""],"RS680-9":["קמ",150,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=150","VY02:RS-680","החיבה — יחוד פנימי","״וז״ע החיבה היינו המשכת בחי׳ עצמות א״ס בחי׳ טוב ה׳ לקויו וזהו שנמשך לאברהם משום ושמרו דרך ה׳ לעשות צדקה ומשפט שהמשיך בחי׳ הפנימיות כו׳״","צילום הדף (COL)","",""],"RS680-10":["קמ",150,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=150","VY02:RS-680","בחירה — כן פי׳ הפנ״י","״הענין הוא שזהו שהידיעה אינה מכרחת את הבחירה (כן פי׳ הפנ״י) שהגם שידוע למעלה מ״מ אברהם עשה זה בבחירתו, ועז״א למען אשר יצוה, שאם הי׳ או׳ כי ידעתיו אשר יצוה הי׳ משמע שע״י הידיעה הי׳ עשי׳ בדרך ממילא עז״א למען אשר יצוה להודיע שאברהם עשה כן בבחירת עצמו כו׳״","צילום הדף (COL)","",""],"RS680-11":["קמ",150,"https://media.col.org.il/files/uploads/original/2019/03/5ca0739b6f0fb_1554019227.pdf#page=150","VY02:RS-680","סיום","״דתכלית הכוונה בבריאת והתהוות העולם הוא להמשיך בחי׳ פנימיות ועצמות א״ס ע״י תומ״צ וכללותם הוא צדקה ומשפט״","צילום הדף (COL)","",""],"RY684-2":["פ",88,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=88","VY02:RY-684","פתיחה ורש״י","״ופי׳ רש״י כי ידעתיו ל׳ חיבה... ולמה ידעתיו למען אשר יצוה לפי אשר יצוה את בניו עלי לשמור דרכי״","צילום הדף (COL)","",""],"RY684-3":["פ",88,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=88","VY02:RY-684","הקושיה","״וצ״ל והלא פשיטות משמעות הענין הוא דזה המשך מהקודם דאברהם היו יהי׳ לגוי גדול ועצום״","צילום הדף (COL)","",""],"RY684-4":["פא",89,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=89","VY02:RY-684","דרך הוי׳ — הגורם","״הנה אחרי כל ההפלאה הזאת אומר כי ידעתיו למה ידעתיו למה זכה אברהם לחבבו לפי אשר יצוה את בניו כו׳״\n\n״וצ״ל מהו״ע דרך הוי׳ דלאחר שאומר לעשות צדקה ומשפט שהם ענינים של פועל, ומהו דרך הוי׳, אלא המובן מזה הוא דיש דרך הוי׳ שזהו הגורם לעשות צדקה ומשפט, ולפי שאברהם יצוה לבניו שישמרו דרך הוי׳ לזאת ידעתיו בחיבה יתירה יותר מכל עבודתו במס״נ וריבוי נסיונות שנתנסה כו׳״","צילום הדף (COL)","",""],"RY684-5":["פא",89,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=89","VY02:RY-684","עבודת אברהם","״וכל עבודתו היתה בכח עצמו ובמס״נ ממש״","צילום הדף (COL)","",""],"RY684-6":["פב",90,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=90","VY02:RY-684","גילוי בגלות ובטבע","״לכך אברהם מצוה לבניו אחריו שמרו דרך ה׳ שיהי׳ גילוי שם הוי׳... דגם בהטבע יהי׳ נראה וניכר הלמע׳ מדרך הטבע״","צילום הדף (COL)","",""],"RY684-8":["צג",101,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=101","VY02:RY-684","יושבי אהל ובעלי עסקים","״הן יושבי אהל והן בעלי עסקים״\n\n״הנה יהי׳ הסכם והחלט אצלו שלא ללכת״","צילום הדף (COL)","",""],"RY684-9":["צג",101,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=101","VY02:RY-684","המצוה — המחבר","״וזהו כי ידעתיו כו׳ ושמרו דרך ה׳, יש דרך דע״י הוא גילוי שם הוי׳ בעולם, ואברהם הוא המצוה, כלומר המחבר שפועל בנש״י שהם בניו וביתו של אברהם אשר ישמרו דרך ה׳ בסוד הבירורים, ואז הנה ע״י הוא לעשות צדקה ומשפט שהם העבודה דתו׳ והעבודה דתפלה״","צילום הדף (COL)","",""],"RY684-11":["מפתח (pdf 5)",5,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=5","VY02:RY-684/מפתח","מפתח: כתיבה והדפסה","״הגהות והתחלת וסוף כל מאמר״\n\n״[הערת כ״ק אדמו״ר שליט״א]״","צילום הדף (COL)","",""],"RY684-12":["מפתח (pdf 5)",5,"https://media.col.org.il/files/uploads/original/2019/03/5ca0904407f72_1554026564.pdf#page=5","VY02:RY-684/מפתח","מפתח: הפניות","״; ובהמשך המפתח: ״כי ידעתיו: ראה רד״ה נתת ליראיך פר״ת (סה״מ פר״ת ע׳ קה), המשך יו״ט של ר״ה תרס״ו בתחלתו״","צילום הדף (COL)","",""],"RY686-1":["מפתח (pdf 4)",4,"https://hebrewbooks.org/pdfpager.aspx?req=31675&pgnum=4","VY02:RY-686","מפתח: זמן אמירה","״כי ידעתיו — וירא, כ׳ מ״ח — קא״","צילום הדף","",""],"RY686-2":["מפתח (pdf 4)",4,"https://hebrewbooks.org/pdfpager.aspx?req=31675&pgnum=4","VY02:RY-686","מפתח: יום הולדת אביו","״כ׳ מ״ח: יום הולדת אביו כ״ק אדמו״ר (מוהרש״ב) נ״ע [ראה ד״ה זה פר״ת״","צילום הדף","",""],"RY688-2":["קנו",374,"https://media.col.org.il/files/uploads/original/2019/05/5ce4e85725e1b_1558505559.pdf#page=374","VY02:RY-688","הפסוק בזה היום","״וזהו חזר ישעי׳ והעמידן על שתים כה אמר ה׳ שמרו משפט ועשו צדקה כו׳ וכמ״ש גבי אברהם כי ידעתיו למען אשר יצוה את בניו כו׳ לעשות צדקה ומשפט״","צילום הדף (COL)","",""],"RY688-3":["קנד",372,"https://media.col.org.il/files/uploads/original/2019/05/5ce4e85725e1b_1558505559.pdf#page=372","VY02:RY-688","התוספת","״והנה קבלה לאבותינו רבותינו מרבינו הגדול אשר קבל מרבו ורבו מרבו דפי׳ זהיר ל׳ זוהר ואור״","צילום הדף (COL)","",""],"RY692-1":["קכ",129,"https://media.col.org.il/files/uploads/original/2019/03/5ca091ed246d3_1554026989.pdf#page=129","VY02:RY-692","כותרת","״בס״ד. ש״פ וירא, כ׳ מ״ח צב״ר, ריגא.״","צילום הדף (COL)","",""],"RY692-2":["קכ",129,"https://media.col.org.il/files/uploads/original/2019/03/5ca091ed246d3_1554026989.pdf#page=129","VY02:RY-692","הפסוק כראיה","״והנה תומ״צ הם דרכי הוי׳ וכמ״ש כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך הוי׳ לעשות צדקה ומשפט וגו׳, דתורה ומצות הם דרכי הוי׳ שהם דרכי חיים, וא״כ מהו אומרו ודרך חיים״","צילום הדף (COL)","",""],"RY692-3":["קכ (הערה 1)",129,"https://media.col.org.il/files/uploads/original/2019/03/5ca091ed246d3_1554026989.pdf#page=129","VY02:RY-692","המו״ל: שמע דא״ח ביום זה","״כמעט בכל שנה ושנה״\n\n״אמר: היום חפצתי לדבר דא״ח – אמר דא״ח ד״ה כי נר מצוה – כי כמעט בכל שנה ושנה הייתי שומע דא״ח מאדמו״ר נ״ע ביום זה, שהוא יום הולדת את אדמו״ר נ״ע״\n\n״. לצד זה, בגשרים — אב שאומר לבנו מאמר ביום בר המצוה שלו, ובן שאומר ״כמעט בכל שנה ושנה הייתי שומע דא״ח מאדמו״ר נ״ע ביום זה״","צילום הדף (COL)","",""],"RY692-4":["קכ (הערה 2)",129,"https://media.col.org.il/files/uploads/original/2019/03/5ca091ed246d3_1554026989.pdf#page=129","VY02:RY-692","המו״ל: יסוד המאמר","״הוא ד״ה כי נר מצוה תרנ״ג... עם שינויים והוספות״","צילום הדף (COL)","",""],"RY707-2":["188",66,"https://media.col.org.il/files/uploads/original/2019/03/5ca0884b982bb_1554024523.pdf#page=66","VY02:RY-707","פתיחה: צוותא","״ולמה ידעתיו למען אשר יצוה לפי שהוא מצוה את בניו עלי לשמור דרכי, היינו תומ״צ, כי מצוה ל׳ צוותא והתקשרות, וזהו למען אשר יצוה התקשרות להמשיך אורו ית׳ בתחתונים, כי ע״י תומ״צ מזכך גופו ומקום מושבו, עד שנשלמה הכוונה העליונה שיהי׳ גילוי עצמות אוא״ס למטה״\n\n״מצוה ל׳ צוותא והתקשרות״","צילום הדף (COL)","",""],"RY707-3":["188",66,"https://media.col.org.il/files/uploads/original/2019/03/5ca0884b982bb_1554024523.pdf#page=66","VY02:RY-707","אדם מקדש עצמו מעט","״אדם מקדש א״ע מעט מקדשין אותו הרבה״","צילום הדף (COL)","",""],"RY707-5":["191",69,"https://media.col.org.il/files/uploads/original/2019/03/5ca0884b982bb_1554024523.pdf#page=69","VY02:RY-707","זיכוך הגוף ומקום המושב","״וזהו החסיד המתחסד עם קונו לתקן גופו ולזככו... וכן עם קן דילי׳ מקום מושבו להאירה באור התורה והעבודה״","צילום הדף (COL)","",""],"RY707-6":["196",74,"https://media.col.org.il/files/uploads/original/2019/03/5ca0884b982bb_1554024523.pdf#page=74","VY02:RY-707","המאמר הבא: כ׳ מרחשון","״בס״ד, ה׳ כ׳ מר״ח תש״ז״","צילום הדף (COL)","",""],"RB736-0":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736/כותרת","כותרת (תוכן הספר)","״ש״פ וירא, כ׳ מרחשון ה׳תשל״ו״\n\n״כי ידעתיו – ש״פ וירא, כ׳ מרחשון ה׳תשל״ו״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-1":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","פתיחה","״כי ידעתיו... ומביא ע״ז בעל יום ההולדת כ״ק אדמו״ר (מהורש״ב) נ״ע בהמשך יום טוב של ראש השנה שחל להיות בשבת (כקביעות שנה זו) תרס״ו פירוש התרגום עה״פ, דכי ידעתיו היינו ארי גלי קדמי, ומבאר שהו״ע הרצון שהוא בגלוי (גלי קדמי), ופירש״י דכי ידעתיו הוא לשון חיבה״\n\n״כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו ושמרו דרך ה׳ לעשות צדקה ומשפט״\n\n״ומביא ע״ז בעל יום ההולדת״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-2":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","השאלה","״דלפירש״י מובן, דכי ידעתיו לשון חיבה למען (בשביל) אשר יצוה גו׳... משא״כ לפירוש התרגום דכי ידעתיו קאי על ענין הרצון, הרי תיבת למען אין לה פירוש כלל״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-3":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","קשר למים רבים תרל״ו","״גם עם המאמר דבן מאה שנה (מש״פ וירא תרל״ו) מכ״ק אדמו״ר מהר״ש [שבעל יום ההולדת הי׳ ממלא מקומו]״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-4":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","מים רבים — טרדות הפרנסה","״המים רבים הם טרדות הפרנסה״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-5":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","סיפור הבעש״ט","״שעושים זאת כדי להשיא בתו לתלמיד חכם וכן לשכור מלמד לבנו״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-6":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","עסק בגשמיות לשם שמים","״והיינו שצ״ל ההתעסקות בדברים הגשמיים בשביל התורה ומצוות, וכדי שיהי׳ כל מעשיך לשם שמים״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-7":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","יצוה — צוותא, עד סוף כל הדורות","״שזה מובן ע״י ביאור הפסוק מים רבים כנ״ל״\n\n״דאיך אפשר להיות ושמרו דרך ה׳ גו׳, זהו ע״י כי ידעתיו שבפירוש התרגום קאי זה על בחי׳ הרצון, הרצון העצמי, עד להרצון שבעצמות. דעי״ז דוקא (למען אשר) יצוה את בניו וגו׳ עד סוף כל הדורות. וזה כולל גם הפירוש ביצוה מלשון צוותא וחיבור״\n\n״עד סוף כל הדורות״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-8":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","נותנים כח — והבחירה חפשית","״אמנם אעפ״כ אין זה באופן דנהמא דכיסופא (שהרצון, ידעתיו, מכריח אותו), כי אם שנותנים לו את הכח ע״ז, ואח״כ פועל זאת בבחירתו. דזהו פירוש התרגום כי ידעתיו, ארי גלי קדמי... ולכן כתיב למען אשר יצוה (ולא ידעתיו אשר יצוה), כי הידיעה אינה מכרחת את הבחירה״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-9":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","למה תרס״ו מביא את הבחירה","״ויש לומר שמביא שם (בתרס״ו) ענין זה (דהידיעה אינה מכרחת) כדי לבאר שאע״פ שהעבודה לברר את הענינים הגשמיים היא ע״י שהרצון העצמי הוא בגלוי (כנ״ל), הנה אעפ״כ אין זה נהמא דכיסופא״","טקסט דיגיטלי (maamarim.com)","",""],"RB736-10":["סה״מ בראשית ח״א ע׳ ריד ואילך",null,"https://maamarim.com/maamar.html?id=gb_946","VY02:RB-736","חיבה ותענוג; גשמיות לרוחניות","״התענוג העצמי הנמשך ע״י מעשה התורה ומצוות... ועד שאין זה נהמא דכיסופא כי זוהי עבודתו (שלו), ואח״כ בא גם בגשמיות, וכמאמר כ״ק אדמו״ר הזקן שהקב״ה נותן לישראל גשמיות והם עושים מגשמיות רוחניות״\n\n״ועד שאין זה נהמא דכיסופא כי זוהי עבודתו (שלו)״","טקסט דיגיטלי (maamarim.com)","",""],"RB747-0":["494",504,"https://media.col.org.il/files/uploads/original/2019/05/5cee68bdcc3a6_1559128253.pdf#page=504","VY02:RB-747S/ע׳ 494","כותרת השיחה","״בס״ד. משיחות ש״פ וירא, כ״ף מרחשון ה׳תשמ״ז.״","צילום הדף (COL)","",""],"RB737-1":["רנה",null,"https://www.chabadlibrary.org/books/1500360308","VY02:RB-737","כותרת ושאלת תרס״ז","״ש״פ וירא, כ״ף מרחשון ה׳תשל״ז״\n\n״בס״ד. ש״פ וירא, כ״ף מרחשון ה׳תשל״ז״\n\n״ומדייק בזה בעל יום ההולדת במאמרו ד״ה זה דשנת תרס״ז (בהמשך תרס״ו), הרי דרך הוי׳ זהו תומ״צ, וא״כ מה מוסיף הכתוב בלעשות צדקה גו׳ (ענין המצוות) על ושמרו דרך הוי׳. ומבאר שם, דדרך הוי׳ היא המשכה מלמעלה למטה, וצדקה ומשפט היא העבודה בבחי׳ מלמטה למעלה, העבודה דאור חוזר״\n\n״ומדייק בזה בעל יום ההולדת״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-2":["רנה",null,"https://www.chabadlibrary.org/books/1500360308","VY02:RB-737","שני המאמרים","״והנה הפסוק כי ידעתיו גו׳ ושמרו דרך הוי׳ לעשות צדקה ומשפט נתבאר בהמשך הנ״ל בד״ה כי ידעתיו דשנת תרס״ו (מאמר דש״פ וירא הראשון שבההמשך), ובמאמר זה (מאמר דש״פ וירא השני שבההמשך״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-2b":["רנה",null,"https://www.chabadlibrary.org/books/1500360308","VY02:RB-737/ספריית חב״ד","מבאר הפסוק באופן אחר","״מבאר הפסוק באופן אחר״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-3":["רנה–רנו",null,"https://www.chabadlibrary.org/books/1500360309","VY02:RB-737","חילוק א׳: ידעתיו","״ומבאר שם דידעתיו לשון ידיעה הו״ע רצון העצמי... וידעתיו לשון חיבה הו״ע תענוג העצמי, משא״כ במאמר השני מפרש ידעתיו לשון חיבה, שחיבב אותו בבחי׳ תענוג העצמי״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-4":["רנו",null,"https://www.chabadlibrary.org/books/1500360309","VY02:RB-737","חילוק ב׳: צדקה ומשפט","״דבמאמר הראשון משמע... דלעשות צדקה ומשפט הוא הפירוש דושמרו דרך הוי׳, או שצדקה ומשפט הוא פרט בדרך הוי׳״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-5":["רנו",null,"https://www.chabadlibrary.org/books/1500360309","VY02:RB-737","ענין נוסף","״ובמאמר זה... מבאר דלעשות צדקה גו׳... הוא לא פירוש או פרט בדרך הוי׳ אלא שהוא ענין נוסף״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-6":["רנו",null,"https://www.chabadlibrary.org/books/1500360309","VY02:RB-737","דרך — ממוצע","״דענין דרך למעלה הוא בדוגמת דרך כפשוטו (בגשמיות), שהוא ממוצע שמחבר שני מקומות שמצד עצמם הם רחוקים זמ״ז בתכלית״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-7":["רנו",null,"https://www.chabadlibrary.org/books/1500360309","VY02:RB-737","דרך המלך","״וכמו דרך המלך הנמשך והולך מעיר המלוכה מקום מושב המלך לכל מרחבי המדינה... עד לפינה הכי נדחת״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-9":["רנז",null,"https://www.chabadlibrary.org/books/1500360310","VY02:RB-737","הליכה וחזרה","״משמש לא רק להליכה אלא גם לחזרה״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-10":["רנח",null,"https://www.chabadlibrary.org/books/1500360311","VY02:RB-737","צדקה, משפט, לעשות","״ומוסיף צדקה ומשפט, דעשיית הצדקה (צדקה כפשוטה) צ״ל במשפט, שישפוט את עצמו מהמותרות ויחשוב היטב מה שהוא מוכרח לנפשו וכל השאר יתן לצדקה... ומוסיף לעשות (צדקה ומשפט), שגם זה... אינו מספיק עדיין, וצריך להיות באופן דאתכפיא, מעשה מלשון כפי׳״\n\n״שישפוט את עצמו מהמותרות״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-11":["רנט",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","התוכן הפנימי: מאמר א׳","״ועפ״ז יש לבאר תוכן הפנימי של החילוקים דהמאמרים דש״פ וירא בהמשך תרס״ו. דבמאמר הראשון מבאר ענין המצוות, זה שע״י קיום המצוות נמשכים ענינים הכי נעלים, רצון עצמי ותענוג עצמי״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-12":["רנט",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","התוכן הפנימי: מאמר ב׳","״ולשנה הבאה במאמר השני מבאר העילוי דמעשה המצוות (עבודת המטה) כמו שהוא מצד עצמו, בדוגמת הגילוי דלעתיד שאז תתגלה מעלת המעשה, מעשה גדול״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-14":["רס",null,"https://www.chabadlibrary.org/books/1500360313","VY02:RB-737","רצון עכשיו, תענוג לעתיד","״[דגילוי תענוג העצמי הוא נעלה יותר מגילוי הרצון, שלכן גילוי הרצון יש גם עכשיו משא״כ גילוי התענוג יהי׳ רק לעתיד]״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-15":["רס",null,"https://www.chabadlibrary.org/books/1500360313","VY02:RB-737","יצוה את בניו — נתינת כח","״והנה שני ענינים אלו דושמרו דרך הוי׳ (המשכה מלמעלה למטה) לעשות צדקה ומשפט (עבודה מלמטה למעלה) ישנם בכאו״א מישראל, במשך כל הדורות. דנוסף על זה שכל עניני התורה הם נצחיים, ובפרט הענינים דמעשה אבות סימן ונתינת כח לבנים, הרי בנוגע לענין זה אומר בפירוש אשר יצוה את בניו ואת ביתו אחריו, עד סוף כל הדורות. וציווי זה (שאברהם מצוה את בניו גו׳) הוא נתינת כח מיוחד (נוסף על הנתינת כח שמצד מעשה אבות) לכל אחד מישראל על שתי עבודות הנ״ל״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-16":["רס",null,"https://www.chabadlibrary.org/books/1500360313","VY02:RB-737","מזמור יום ההולדת","״אתהלך לפני הוי׳ בארצות החיים״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-17":["רנט (הערה 42)",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","הערה 42: הקביעות","״להעיר שהקביעות דיום ההולדת (כ׳ מרחשון) בשנת תרס״ו היתה בש״ק פ׳ וירא אליו הוי׳ – גילוי מלמעלה״\n\n״להעיר שהקביעות דיום ההולדת (כ׳ מרחשון) בשנת תרס״ו היתה בש״ק פ׳ וירא אליו הוי׳ – גילוי מלמעלה, והקביעות דיום ההולדת בשנת תרס״ז היתה ביום ה׳ פ׳ חיי שרה – כמה ימים דעבודה כמו שהיא לאחרי הגילוי מלמעלה״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-18":["רנט (הערה 42)",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","הערה 42: וירצבורג","״ולהעיר גם מזה שבכל השנים (משנת תרנ״ד עד שנת תרע״ו) הי׳ אדמו״ר נ״ע בעל יום ההולדת בליובאַוויטש, מלבד בשנת תרס״ז שהי׳ אז בחו״ל, בוירצבורג... ואולי יש לומר, שגם ענין זה... שייך לעבודת הבירורים״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-19":["רנט (הערה 42*)",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","הערה 42*: וירא","״שעוד בהיותו ילד השתוקק לזה ועד לבכי׳״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-20":["רנט (הערה 42**)",null,"https://www.chabadlibrary.org/books/1500360312","VY02:RB-737","הערה 42**: ארבע קביעויות","״להעיר שקביעות דכ׳ מרחשון (שהוא כמו הקביעות דיום א׳ דראש השנה) יכול להיות בד׳ ימים... וכשהקביעות דכ׳ מ״ח הוא ביום ה׳ – הוא ריבוי הכי גדול בימי העבודה שלאחרי הגילוי״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-21":["רנה (הערה *)",null,"https://www.chabadlibrary.org/books/1500360308","VY02:RB-737","הערה *: פרסום","״יצא לאור בקונטרס כ״ף מרחשון – תשמ״ז״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-25":["רנח (הערה 34)",null,"https://www.chabadlibrary.org/books/1500360311","VY02:RB-737","הערה 34","״ראה גם תו״א בשלח סג, סע״ב״","טקסט דיגיטלי בספריית חב״ד","",""],"RB737-30":["רסא",null,"https://www.chabadlibrary.org/books/1500360314","VY02:RB-737","סיום","״שאז יתגלה העילוי דהעלאת התחתון, מעשה גדול, בביאת משיח צדקנו במהרה בימינו ממש״","טקסט דיגיטלי בספריית חב״ד","",""],"RB747-2":["501",511,"https://media.col.org.il/files/uploads/original/2019/05/5cee68bdcc3a6_1559128253.pdf#page=511","VY02:RB-747S","הקביעות","״הקביעות דכ״ף מרחשון היא לעולם באותו יום בשבוע שבו חל ראש השנה״","צילום הדף (COL)","",""],"RB747-3":["501",511,"https://media.col.org.il/files/uploads/original/2019/05/5cee68bdcc3a6_1559128253.pdf#page=511","VY02:RB-747S","חינוך בפרשת וירא","״מצינו הדגשה מיוחדת... הן בנוגע לענין החינוך (ובפרטיות יותר — חינוך עצמו וחינוך הזולת)״","צילום הדף (COL)","",""],"RB747-5":["501",511,"https://media.col.org.il/files/uploads/original/2019/05/5cee68bdcc3a6_1559128253.pdf#page=511","VY02:RB-747S","חינוך הזולת","״צדקה — כללות כל המצוות״\n\n״חינוך הבנים והבנות (כולל ״בניך אלו התלמידים״","צילום הדף (COL)","",""],"M577-4":["ס",null,"https://www.chabadlibrary.org/books/1900740011","VY02:MZ-577","מותרות","״רק מהסך הנשאר אחר בזבוז על המותרות״","טקסט דיגיטלי בספריית חב״ד","",""],"MH627-24":["יח–יט",28,"https://media.col.org.il/files/uploads/original/2019/03/5ca06234cafd1_1554014772.pdf#page=28","VY02:MH-627","שמש ולבנה","״עני דלית לי׳ מגרמי׳ כלום״","צילום הדף (COL)","",""],"RS666-19":["צח",106,"https://media.col.org.il/files/uploads/original/2019/05/5cd93c1899b6b_1557740568.pdf#page=106","VY02:RS-666","תופס בעצם המהות","״גם אם אינם כדבעי״","צילום הדף (COL)","",""],"AZH-1":["הוספות/וירא, ע׳ 6",520,"https://media.col.org.il/files/uploads/original/2019/03/5c9c9109c32f5_1553764617.pdf#page=520","VY02:AZ-HOS","דרך הוי׳ כמשל דרך הגשמי (בקרה)","״פי׳ דרך הוי׳ כמשל דרך הגשמי שבו עוברים ממקום למקום כן ארחות הוי׳ חסד כו׳ המתפשט מלמעלה למטה מאצי׳ לבי״ע, ויש חסד העולה מלמטה למעלה״\n\n״דרך הגשמי שבו עוברים ממקום למקום״","צילום הדף (COL)","",""],"MZTC-5":["קע, א (עמ׳ 339)",341,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=341","VY02:MZ-TC","צדקה ומשפט — ב׳ הפכים (בקרה)","״דלכאו׳ הצדקה והמשפט הן ב׳ הפכים״","צילום הדף (COL)","",""],"MZTC-6":["קעא, ג (עמ׳ 342)",344,"https://media.col.org.il/files/uploads/original/2019/03/5c9fbe5f1e0fe_1553972831.pdf#page=344","VY02:MZ-TC","רחמי המלך מול השר (בקרה)","״כמו המלך המרומם ביותר שירחם על העני ושפל יותר מעל השר הגדול״","צילום הדף (COL)","",""],"RB737-31":["פתח דבר, ע׳ iii",4,"https://media.col.org.il/files/uploads/original/2018/11/15403809575bd0591d7649770654.pdf#page=4","VY02:RB-737/פתח דבר","מעמד ההגהה של הסדרה (בקרה)","״אשר הוגהו על ידו״\n\n״הכולל את כל מאמרי החסידות של כ״ק אדמו״ר... אשר הוגהו על ידו״","צילום הדף (COL)","",""]},"parts":[{"id":"intro","title":"פתח דבר: פסוק אחד, שבעה דורות, ושבת אחת שבה הפרשה והיום נפגשים"},{"id":"ch-א","title":"א. השורש: צדקה ומשפט הם ״דרך כלל״ כל המצוות, והמשפט הוא גבול לתענוגות"},{"id":"ch-ב","title":"ב. מהר״ש: ממאמר של הצמח צדק — המבנה שחוזר אחריו"},{"id":"ch-ג","title":"ג. הרש״ב, תרס״ו: בלשון ״וי״ל״ — ״ידיעה״ היא הרצון, ״חיבה״ היא התענוג"},{"id":"ch-ד","title":"ד. הרש״ב, תרס״ז: ״דרך ה׳״ מלמעלה, ״צדקה ומשפט״ מלמטה"},{"id":"ch-ה","title":"ה. הרש״ב, פר״ת: מאמר מהר״ש עם ״תוס׳ ביאור והוספות״ — משפיע ומקבל, רחמי המלך, ונימוק לבחירה"},{"id":"ch-ו","title":"ו. הריי״צ: למה החיבה תלויה ב״יצוה״, ומה פירוש ״יצוה״"},{"id":"ch-ז","title":"ז. הרבי, תשל״ו: הרצון נותן כוח, והבחירה נשארת שלו"},{"id":"ch-ח","title":"ח. הרבי, תשל״ז: שני המאמרים של הרש״ב, ו״אשר יצוה את בניו״ כנתינת כוח לכל אחד מישראל"},{"id":"ch-ט","title":"ט. כ׳ מרחשון בגשרים: בר מצוה, ״כמעט בכל שנה ושנה״, וחינוך"},{"id":"ch-י","title":"י. מה עולה מן השרשרת"},{"id":"sources","title":"מקורות"},{"id":"open","title":"פתוח לבקרה"}]});
